import { IconCar, IconPet, IconReservation } from 'components/AppIcon'
import { StatusBadge, StyledCard } from './style'
import { AppCardProps } from './types'

const OPEN_STATUS = {
	Y: 'เปิดอยู่',
	N: 'ปิดแล้ว',
}

export const AppCard = ({ data }: AppCardProps) => {
	const {
		shopNameTH,
		subcategoryName,
		coverImageId,
		facilities,
		priceLevel,
		isOpen,
		highlightText,
		recommendedItems,
		addressProvinceName,
		addressDistrictName,
	} = data

	const safeHighlightText = highlightText
		.replace(/\</g, '&lt;')
		.replace(/\>/g, '&gt;')
		.replace(/&lt;strong&gt;/g, '<strong>')
		.replace(/&lt;\/strong&gt;/g, '</strong>')

	const getIcon = (criteria, key) => {
		if (criteria === 'รับจองล่วงหน้า')
			return <IconReservation key={key} color="#1fc300" size="1.5rem" />
		if (criteria === 'สามารถนำสัตว์เลี้ยงเข้าได้')
			return <IconPet key={key} color="#1fc300" size="1.5rem" />
		return <IconCar key={key} color="#1fc300" size="1.5rem" />
	}

	return (
		<StyledCard>
			<img src={coverImageId} alt={shopNameTH} />
			<section>
				<header>
					<h2>
						{shopNameTH}
						{isOpen !== 'N/A' && (
							<StatusBadge success={isOpen === 'Y'}>{OPEN_STATUS[isOpen]}</StatusBadge>
						)}
					</h2>
					<span>
						{subcategoryName} |{' '}
						<span className="nobr">
							<span className="money">{'฿'.repeat(priceLevel)}</span>
							{'฿'.repeat(4 - priceLevel)}
						</span>{' '}
						|{' '}
						<span className="nobr">
							{addressDistrictName}&nbsp;{addressProvinceName}
						</span>
					</span>
				</header>
				<hr />
				<p dangerouslySetInnerHTML={{ __html: safeHighlightText }}></p>
				<p>
					<strong>เมนูแนะนำ:</strong> {recommendedItems.join(' ')}
				</p>
				<footer>{facilities.map((f, i) => getIcon(f, i))}</footer>
			</section>
		</StyledCard>
	)
}

