  }

  export class IntersectionTypeNode extends TypeNode {
    of: TypeNode[] = [];

    get childrenOrEmpty() {
      return this.of || [];
    }
  }

  export class StructDeclarationNode extends TypeNode {
    isPublic: boolean = true;
    constructor(
      astNode: ASTNode,
      public readonly declaredName: NameIdentifierNode,
      public readonly parameters: ParameterNode[]
    ) {
      super(astNode);
    }

    get childrenOrEmpty() {
      return [this.declaredName, ...(this.parameters || [])];
    }
  }

  export class EffectDeclarationNode extends Node {
    elements?: FunctionTypeNode[];

    constructor(astNode: ASTNode, public readonly name: NameIdentifierNode) {
      super(astNode);
    }

    get childrenOrEmpty() {
      return [this.name, ...(this.elements || [])];
    }
  }

  export class MatchDefaultNode extends MatcherNode {}

  export class PatternMatcherNode extends ExpressionNode {
    carryType?: Type;

    constructor(astNode: ASTNode, public readonly lhs: ExpressionNode, public readonly matchingSet: MatcherNode[]) {
      super(astNode);
    }

    get childrenOrEmpty(): Node[] {
      return [this.lhs, ...(this.matchingSet || [])];
    }
  }

  export class LoopNode extends ExpressionNode {
    constructor(astNode: ASTNode, public readonly body: ExpressionNode) {
      super(astNode);
    }

    get childrenOrEmpty() {
      return [this.body];
    }
  }

  export class ContinueNode extends Node {
    get childrenOrEmpty() {
      return [];
    }
  }

  export class BreakNode extends Node {
    get childrenOrEmpty() {
      return [];
    }
  }
}

export function findNodesByType<T>(
  astRoot: { children: any[] },
  type: { new (...args: any[]): T },
  list: T[] = []
): T[] {
  if (astRoot instanceof type) {
    list.push(astRoot);
  }
  astRoot.children.forEach($ => findNodesByType($, type, list));
  return list;
}

export function findNodesByTypeInChildren<T>(
  astRoot: { children: any[] },
  type: { new (...args: any[]): T },
  list: T[] = []
): T[] {
  astRoot.children.forEach($ => {
    if ($ instanceof type) {
      list.push($);
    }
  });
  return list;
}

import { TestInfo, TestSuiteInfo } from 'vscode-test-adapter-api';
import { TestType } from '../../../core/base/test-infos';
import { SpecLocator } from '../../../core/spec-locator';
import { Logger } from '../../../util/logging/logger';
import { SpecCompleteResponse } from './spec-complete-response';

export class SpecResponseToTestSuiteInfoMapper {
  public constructor(private readonly specLocator: SpecLocator, private readonly logger: Logger) {}

  public map(specs: SpecCompleteResponse[]): TestSuiteInfo {
    const rootTestSuite: TestSuiteInfo = this.createRootSuite();
    const unreferencedDuplicateSpecFilesBySpec: Map<string, string[]> = new Map();

    let processedSpecCount = 0;

    specs.forEach(rawSpec => {
      const spec: SpecCompleteResponse = { ...rawSpec, suite: this.filterSuiteNoise(rawSpec.suite) };
      const matchingSpecLocations = this.specLocator.getSpecLocation(spec.suite, spec.description);
      let specFile: string | undefined = spec.filePath;

      if (matchingSpecLocations.length === 1) {
        specFile = specFile ?? matchingSpecLocations[0].file;
      } else if (matchingSpecLocations.length > 1) {
        if (!unreferencedDuplicateSpecFilesBySpec.has(spec.fullName)) {
          unreferencedDuplicateSpecFilesBySpec.set(
            spec.fullName,
            matchingSpecLocations.map(loc => loc.file)
          );
        }
        const unreferenceMatchingSpecFiles = unreferencedDuplicateSpecFilesBySpec.get(spec.fullName)!;
        specFile = specFile ?? unreferenceMatchingSpecFiles[0];

        if (unreferenceMatchingSpecFiles.includes(specFile)) {
          unreferenceMatchingSpecFiles.splice(unreferenceMatchingSpecFiles.indexOf(specFile), 1);
        }
      }

      if (!specFile) {
        this.logger.debug(() => `Skipped spec with undetermined source file - spec Id: ${spec.id}`);
        this.logger.trace(() => `Spec with undetermined source file: ${JSON.stringify(spec)}`);
        return;
      }
      const testSuite = this.getDescendantSuite(rootTestSuite, spec.suite, specFile);
      const test = this.createTest(spec, specFile);
      testSuite.children.push(test);
      processedSpecCount += 1;
    });

    this.logger.debug(() => `Mapped ${processedSpecCount} tests from specs`);
    return rootTestSuite;
  }

  private createRootSuite(): TestSuiteInfo {
    const rootSuite: TestSuiteInfo = {
      type: TestType.Suite,
      id: ':',
      label: 'Karma tests',
      fullName: '', // To prevent being runnable with grep pattern of fullName
      children: [],
      testCount: 0
    };
    return rootSuite;
  }

  private getDescendantSuite(baseNode: TestSuiteInfo, suitePath: string[], specFile: string): TestSuiteInfo {
    const currentSuitePath: string[] = [];
    let currentNode: TestSuiteInfo = baseNode;

    for (const suiteName of suitePath) {
      currentSuitePath.push(suiteName);

      let nextNode =
        currentNode.label === suiteName && currentNode.file === specFile
          ? currentNode
          : (currentNode.children.find(child => {
              return child.type === TestType.Suite && child.label === suiteName && child.file === specFile;
            }) as TestSuiteInfo | undefined);

      if (!nextNode) {
        nextNode = this.createSuite(currentSuitePath, specFile);
        currentNode.children.push(nextNode);
      }
      currentNode = nextNode;
    }
    return currentNode;
  }

  private createSuite(suitePath: string[], suiteFile: string): TestSuiteInfo {
    const allMatchingSuiteLocations = this.specLocator.getSpecLocation(suitePath);
    const suiteLocation = allMatchingSuiteLocations.find(loc => loc.file === suiteFile);
    const suiteName = suitePath[suitePath.length - 1];
    const suiteFullName = suitePath.join(' ');
    const suiteId = `${suiteFile}:${suiteFullName}`;

    const hasDuplicates = allMatchingSuiteLocations.length > 1;
    let message: string | undefined;

    if (hasDuplicates) {
      let duplicateSuiteCounter = 0;

      const duplicateSuiteFiles = allMatchingSuiteLocations
        .sort((loc1, loc2) => (loc1.file === suiteFile ? -1 : loc2.file === suiteFile ? 1 : 0))
        .map(location => `${++duplicateSuiteCounter}. ${location.file}:${location.line + 1}`)
        .join('\n');

      message =
        `"${suiteFullName}" \n\n` +
        '---------- \n\n' +
        'The above test suite has duplicate definitions in the following files ' +
        'in your project which could lead to conflicting test results: \n\n' +
        `${duplicateSuiteFiles}`;
    }

    const suiteNode: TestSuiteInfo = {
      type: TestType.Suite,
      id: suiteId,
      fullName: suiteFullName,
      label: suiteName,
      tooltip: suiteFullName,
      children: [],
      testCount: 0,
      file: suiteLocation?.file,
      line: suiteLocation?.line,
      message
    };
    return suiteNode;
  }

  private createTest(spec: SpecCompleteResponse, specFile: string): TestInfo {
    const allMatchingSpecLocations = this.specLocator.getSpecLocation(spec.suite, spec.description);
    const specLocation = allMatchingSpecLocations.find(loc => loc.file === specFile);

    const runFailureMessage = spec.failureMessages?.join('\n');
    let loadFailureMessage: string | undefined;

    let file = spec.filePath;
    let line = spec.line;
    let errored = false;

    if (!file || line === undefined) {
      file = specLocation?.file;
      line = specLocation?.line;
      const hasDuplicates = allMatchingSpecLocations.length > 1;

      if (hasDuplicates) {
        errored = true;
        let duplicateSpecCounter = 0;

        const duplicateSpecFiles = allMatchingSpecLocations
          .sort((loc1, loc2) => (loc1.file === specFile ? -1 : loc2.file === specFile ? 1 : 0))
          .map(location => `${++duplicateSpecCounter}. ${location.file}:${location.line + 1}`)
          .join('\n');

        loadFailureMessage =
          `"${spec.fullName}" \n\n` +
          '---------- \n\n' +
          'The above test has duplicate definitions in the following locations ' +
          'in your project which could lead to conflicting test results: \n\n' +
          `${duplicateSpecFiles}`;
      }
    }

    const test: TestInfo = {
      type: TestType.Test,
      id: spec.id,
      fullName: spec.fullName,
      label: spec.description,
      tooltip: spec.fullName,
      message: runFailureMessage || loadFailureMessage,
      file,
      line,
      errored
    };
    return test;
  }

  private filterSuiteNoise(suitePath: string[]) {
    if (suitePath.length > 0 && 'Jasmine__TopLevel__Suite' === suitePath[0]) {
      suitePath = suitePath.slice(1);
    }
    return suitePath;
  }
}

import { Component, Element, Event, EventEmitter, h, Listen, Method, Prop, State, Watch } from '@stencil/core'
import { ServiceController } from '../../service'
import { i18n } from '../../i18n/translator'
import { Util } from '../../utils'
@Component({
  tag: 'mep-listing',
  styleUrl: 'mep-listing.scss'
})
export class MepListing {

  @Element() $el: HTMLElement

  @Prop({ attribute: 'page-size' }) pageSize: number = 20
  @Prop({ attribute: 'list-id' }) listId: string
  @Prop({ mutable: true }) filters: any = ''
  @Prop() url: string

  @State() list: Array<any> = []
  @State() columns: Array<any> = []
  @State() pageNo: number = 1
  @State() isLoading: boolean = false
  @State() appliedFilter: any = {}
  @State() filterOpen: boolean = false
  @State() totalRecords: number = 0
  @State() hasFilterErrors: boolean = false

  @Event({
    eventName: 'cell-click',
    composed: true,
    cancelable: true,
    bubbles: true,
  }) cellClickEvent: EventEmitter
  @Event({
    eventName: 'on-load',
    composed: true,
    cancelable: true,
    bubbles: true,
  }) onLoadEvent: EventEmitter

  headerSlot: HTMLElement
  filterSlot: HTMLElement
  footerSlot: HTMLElement
  sidePanel: HTMLElement
  titleSlot: HTMLElement
  cellClick: Function
  onApplyFilter: Function
  onLoad: Function
  generateRowItem: Function

  componentWillLoad() {
    this.headerSlot = this.$el.querySelector('[slot="header"]')
    this.filterSlot = this.$el.querySelector('[slot="filter"]')
    this.sidePanel = this.$el.querySelector('[slot="side-panel"]')
    this.titleSlot = this.$el.querySelector('[slot="table-title"]')
    // if (this.sidePanel) {
    //   const nodes = Util.textNodesUnder(this.sidePanel)
    //   console.log(nodes)
    //   nodes.forEach(node => {
    //     node.data = Util.format(node.data, this)
    //   })
    // }
    this.footerSlot = this.$el.querySelector('[slot="footer"]')
    this.filters = this.filters && JSON.parse(this.filters)
    if (this.$el.getAttribute('cell-click')) {
      this.cellClick = window[this.$el.getAttribute('cell-click')]
    }
    if (this.$el.getAttribute('on-load')) {
      this.onLoad = window[this.$el.getAttribute('on-load')]
    }
    if (this.$el.getAttribute('on-filter')) {
      this.onApplyFilter = window[this.$el.getAttribute('on-filter')]
    }
    this.onFirstLoad()
  }
  componentDidLoad() {
    this.registerListeners()
  }
  componentDidRender() {
    this.$el.querySelectorAll('.ellipsify-title').forEach((elem: HTMLElement) => {
      if (parseFloat(window.getComputedStyle(elem).width) === parseFloat(window.getComputedStyle(elem.parentElement).width)) {
        elem.setAttribute('title', elem.textContent)
      }
    })
  }

  @Watch('hasFilterErrors')
  watchStateHandler() {
    if (this.hasFilterErrors) {
      setTimeout(() => {
        this.hasFilterErrors = false
      }, 3000)
    }
  }
  get filterList() {
    return this.list || []
  }
  get filterString() {
    let searchString = ''
    if (this.appliedFilter) {
      for (let prop in this.appliedFilter) {
        if (this.appliedFilter[prop]) {
          searchString += `&${prop}_like=${this.appliedFilter[prop]}`
        }
      }
    }
    return searchString
  }
  get filterCount() {
    return Object.values(this.appliedFilter).filter(val => val).length
  }
  get filterTemplate() {
    return this.filterSlot ? <div class="filter">
      <div onClick={this.toggleFilter.bind(this)} class="icon-container">
        <div class={this.filterOpen ? 'filter-icon open' : 'fa fa-filter'} >
          <span />
          <span />
          <span />
          <p class={`filter-badge ${this.filterCount && !this.filterOpen ? 'applied' : 'open'}`} >{this.filterCount}</p>
        </div>
      </div>
      <div class={`mep-filter-content ${this.filterOpen && 'open'}`}>
        <slot name="filter">
          <slot name="header" />
          <slot name="content" />
          <slot name="footer" />
        </slot>
      </div>
      <div class="table-title">
        <slot name="table-title" />
      </div>
    </div> :
      <div class="filter">
        {
          this.filters.length ? <div onClick={this.toggleFilter.bind(this)} class="icon-container">
            <div class={this.filterOpen ? 'filter-icon open' : 'filter-icon'} >
              <i class="fa fa-filter mx-branding-text"></i>
              <span />
              <span />
            </div>
            <span class={`mx-branding-background filter-badge ${this.filterCount && !this.filterOpen ? 'applied' : 'open'}`} >{this.filterCount}</span>
          </div> : ''
        }
        {
          this.filters.length ? <div class={`mep-filter-content ${this.filterOpen && 'open'}`}>
            <slot name="filter-header" />
            <div id="filterSlot" class="filter-grid">
              {
                this.filters.map(filter => {
                  return <div class="grid-column">
                    {
                      filter.type === 'dropdown' ?
                        <mep-dropdown
                          mep-name={filter.name}
                          list-id={filter.listId}
                          name={filter.name}
                          value={filter.value}
                          label={filter.label}
                          placeholder={filter.placeholder}
                          filter-payload={JSON.stringify(filter.filterPayload)}
                          page-size={filter.pageSize}
                          multiple={filter.multiple}
                          is-dependent={filter.isDependent}
                          dependent-list-id={filter.dependentListId}
                          searchable={filter.searchable}>
                        </mep-dropdown>
                        : filter.type === 'date' ?
                          <mep-datepicker
                            mep-name={filter.name || `${filter.fromName}_${filter.toName}`}
                            name={filter.name}
                            label={filter.label}
                            value={filter.value}
                            fill-default={filter.fillDefault}
                            is-range={filter.isRange}
                            max-range={filter.maxRange}
                            separator={filter.seperator}
                            from-name={filter.fromName}
                            from-value={filter.fromValue}
                            to-name={filter.toName}
                            to-value={filter.toValue}
                            timezone={filter.timezone}
                            disable-past={filter.disablePast}
                            disable-future={filter.disableFuture}
                            disp-format={filter.dispFormat}
                            data-format={filter.dataFormat}
                            placeholder={filter.placeholder}>
                          </mep-datepicker> :
                          <mep-input
                            mep-name={filter.name}
                            type={filter.type}
                            name={filter.name}
                            label={filter.label}
                            value={filter.value}
                            placeholder={filter.placeholder}>
                          </mep-input>
                    }
                  </div>
                })
              }
            </div>
            <div class="filter-footer">
              <div class="error-msg ellipsify-title">{this.hasFilterErrors && i18n['list_filter_validation_msg']}</div>
              <button class="btn btn-light btn-sm"
                style={{ 'font-size': '14px' }}
                onClick={this.resetFilter.bind(this)}
                data-i18n='reset'
              >{i18n['reset']}</button>
              <button class="btn btn-primary btn-sm" style={{ 'font-size': '14px', 'margin-left': '15px' }}
                onClick={this.filterData.bind(this)}
                data-i18n='apply'
              >{i18n['apply']}</button>
            </div>
          </div> : ''
        }
        {
          this.titleSlot ? <div class="table-title">
            <slot name="table-title" />
          </div> : ''
        }
      </div>
  }

  resetFilter() {
    this.setFilterValues({})
  }
  private setFilterValues(filter) {
    const filterSlot = this.filterSlot || this.$el.querySelector('#filterSlot')
    let appliedFilter = {}
    if (filterSlot) {
      let inputs = filterSlot.querySelectorAll("input, select, checkbox, textarea, radio")
      inputs.forEach((input: HTMLInputElement) => {
        const value = filter[input.name] || ''
        if (input.name) {
          input.value = value
          input.checked = !!value
          const event = new CustomEvent('value-changed', { detail: { value: value, name: input.name } })
          input.dispatchEvent(event)
          appliedFilter[input.name] = value
        }
      })
    }
    return appliedFilter
  }

  isFilterChanged(latest) {
    return Object.keys(latest).some(prop => (latest[prop] !== (this.appliedFilter[prop] || '')))
  }
  @Method()
  async filterData(payload, forceCall, togleFilter = true) {
    if (payload && !payload.currentTarget) {
      payload = this.setFilterValues(payload)
    } else if (this.filterSlot || this.filters.length) {
      const filterSlot = this.filterSlot || this.$el.querySelector('#filterSlot')
      let inputs = filterSlot ? filterSlot.querySelectorAll("input, select, textarea") : []
      payload = {}
      inputs.forEach((input: HTMLInputElement) => {
        if (input.name) {
          payload[input.name] = input.value
        }
      })
    } else {
      payload = {}
    }
    const callReq = this.isFilterChanged(payload)
    this.validateFilter(payload)
    if ((callReq && !this.hasFilterErrors) || forceCall) {
      this.appliedFilter = payload
      togleFilter && this.toggleFilter()
      this.pageNo = 1
      this.loadData(forceCall)
    }
  }
  private validateFilter(payload = null) {
    if (this.onApplyFilter) {
      let errors = payload && this.onApplyFilter({ ...payload })
      if (errors && Object.keys(errors).length) {
        for (let name in errors) {
          const item = document.querySelector(`[mep-name=${name}]`) as any
          item && item.toggleErrorMsg(errors[name])
        }
        this.hasFilterErrors = true
      } else {
        this.filters.forEach(filter => {
          const name = filter.name || `${filter.fromName}_${filter.toName}`
          const item = document.querySelector(`[mep-name=${name}]`) as any
          item && item.toggleErrorMsg('')
        })
        this.hasFilterErrors = false
      }
    }
  }
  private loadData(forceCall = false) {
    if (!this.hasFilterErrors || forceCall) {
      if (!this.isLoading) {
        this.isLoading = true
        Util.showSpinner()
      }
      return ServiceController.fetchListData({
        listId: this.listId,
        listUrl: this.url,
        pageSize: this.pageSize,
        pageNo: this.pageNo,
        filter: this.appliedFilter
      }).then(res => {
        this.list = res.data.list
        this.totalRecords = res.data.total
      }).catch((e) => {
        console.trace(e)
      }).finally(() => {
        Util.hideSpinner()
        this.isLoading = false
      })

    }
  }

  cellClickHandler(row: any, column: any, event: Event) {
    if (this.cellClick) {
      this.cellClick.call(null, { event, detail: { row, column } })
    } else {
      this.cellClickEvent.emit({ row, column })
    }
  }
  @Listen('page-change')
  pageCanged(page) {
    this.pageNo = page.detail
    this.loadData()
  }
  toggleFilter() {
    this.filterOpen = !this.filterOpen
    if (!this.filterOpen) {
      this.setFilterValues(this.appliedFilter)
      this.validateFilter()
    }
  }

  private registerListeners() {
    if (this.filterSlot) {
      const filterBtn = this.filterSlot.querySelector(`#filterBtnId`)
      const resetBtn = this.filterSlot.querySelector(`#resetBtnId`)
      if (filterBtn) {
        filterBtn.addEventListener('click', this.filterData.bind(this))
      }
      if (resetBtn) {
        resetBtn.addEventListener('click', this.resetFilter.bind(this))
      }
    }
    setTimeout(() => {
      this.filterData(null, false, false)
    }, 500)
  }

  private onFirstLoad() {
    Util.showSpinner()
    this.isLoading = true
    ServiceController.fetchListConfig({ listId: this.listId }).then(res => {
      this.columns = res.columnConfig
      this.filters = res.filterConfig ? res.filterConfig : this.filters
      this.generateRowItem = new Function('item', 'callback', 'getByPath', Util.generateRowScript(this.columns))
      const payload = this.filters.length && this.filters.reduce((acc, cur) => {
        acc[cur.name] = cur.value || ''
        return acc
      }, {}) || {}
      this.appliedFilter = Object.keys(this.appliedFilter).length ? this.appliedFilter : payload
      this.validateFilter(payload)
      this.loadData()
      setTimeout(() => {
        if (this.onLoad) {
          this.onLoad.call(null, { filters: this.filters, columns: this.columns })
        } else {
          this.onLoadEvent.emit({ filters: this.filters, columns: this.columns })
        }
      }, 200)
    }).catch((e) => {
      console.trace(e)
    })

  }

  render() {
    let headerSlot = this.headerSlot ? <div class="header"><slot name="header" /></div> : ''
    let footerSlot = this.footerSlot ? <div class="footer"><slot name="footer" /></div> : ''
    const style = { height: `calc(100vh - ${this.$el.getBoundingClientRect().top}px)`, width: `calc(100vw - ${this.$el.getBoundingClientRect().left}px)` }
    let containerStyle = { height: `calc(100% - 40px)` }
    if (this.filterSlot || this.filters.length || this.titleSlot) {
      containerStyle = { height: `calc(100% - 75px)` }
    }
    return (
      <div class="mep-listing" style={style} >
        {headerSlot}
        {this.filterTemplate}
        <div class="list-container" style={containerStyle}>
          <table>
            <thead>
              <tr>
                {this.columns.map(col => {
                  let st = {}
                  st['width'] = `${col.width || '100px'}`
                  return <th><div class="table-header" style={st}><span class="ellipsify-title" data-i18n={col.label}>{i18n[col.label]}</span></div></th>
                })}
              </tr>
            </thead>
            <tbody>
              {
                this.filterList.length ?
                  this.filterList.map(item => <tr ref={
                    nodeEle => {
                      while (nodeEle && nodeEle.firstChild) {
                        nodeEle.lastChild.remove()
                      }
                      if (nodeEle) {
                        const tds = this.generateRowItem(item, this.cellClickHandler.bind(this), Util.getByPath.bind(this))
                        tds.forEach(td => {
                          nodeEle.appendChild(td)
                        })
                        // nodeEle.append(...this.generateRowItem(item, this.cellClickHandler.bind(this), Util.getByPath.bind(this)))
                      }
                    }
                  } />) : <tr class="no-data-found" ref={
                    nodeEle => {
                      while (nodeEle && nodeEle.firstChild) {
                        nodeEle.lastChild.remove()
                      }
                      if (nodeEle && !this.isLoading) {
                        nodeEle.innerHTML = `<td>${i18n['no_data_found']}</td>`
                      }
                    }}></tr>
              }
            </tbody>
          </table >
        </div>
        <mep-pagination page-size={this.pageSize} total-count={this.totalRecords} current-page={this.pageNo} />
        {footerSlot}
      </div >
    )
  }
}

import {Component, QueryList, ViewChild, ViewChildren, ViewContainerRef} from '@angular/core';
import {LogService} from '../../../services/log.service';
import {Subject} from 'rxjs';
import {MatRow, MatTable, MatTableDataSource} from '@angular/material/table';
import {NgScrollbar} from 'ngx-scrollbar';
import {takeUntil} from 'rxjs/operators';
import {Stakeholder} from '../../../model/Stakeholder';
import {MatSort} from '@angular/material/sort';

@Component({
  selector: 'app-entity-table',
  templateUrl: './entity-table.component.html',
  styleUrls: ['./entity-table.component.scss']
})
export class EntityTableComponent {

  protected ngUnsubscribe = new Subject();

  // Properties that must be in the template of the child.
  @ViewChild(NgScrollbar) scrollbarRef!: NgScrollbar;
  @ViewChild(MatTable) table!: MatTable<Stakeholder>;
  @ViewChild(MatSort) sort: MatSort = new MatSort();
  @ViewChildren(MatRow, {read: ViewContainerRef}) rows!: QueryList<ViewContainerRef>;

  // Properties that must be assigned by the child.
  displayedColumns: string[] = [];
  tableDataSource = new MatTableDataSource<any>();
  filterEvent!: any;

  // Properties that must be left unchanged by the child.
  windowScrolled = false;
  highlightFilter = '';

  constructor(protected logger: LogService) {

  }

  // Lifecycle events.
  onInit(): void {

  }

  afterViewInit(): void {
    this.scrollbarRef?.scrolled
      .pipe(takeUntil(this.ngUnsubscribe))
      .subscribe(e => {
        this.windowScrolled = e.target.scrollTop !== 0;
      });

    this.initSorting();
    this.initFiltering();
  }

  onDestroy(): void {
    this.ngUnsubscribe.next();
    this.ngUnsubscribe.complete();
  }

  // Abstract methods (they are not abstract, because a base component cannot be abstract).
  updateTableDataSource(): void {
  }

  createDataAccessor(): (stakeholder: any, property: string) => any {
    return (stakeholder: any, property: string) => null;
  }

  createFilterPredicate(): (data: any, filter: string) => boolean {
    return (data: any, filter: string) => true;
  }

  // Methods.
  initSorting(): void {
    this.logger.trace(this, 'Init Sorting');
    this.tableDataSource.sort = this.sort;
    this.tableDataSource.sortingDataAccessor = this.createDataAccessor();
  }

  initFiltering(): void {
    this.logger.trace(this, 'Init Filtering');
    this.tableDataSource.filterPredicate = this.createFilterPredicate();
  }

  scrollToTop(): void {
    this.logger.trace(this, 'Scroll To Top');
    const options = {top: 0, duration: 250};
    this.scrollbarRef.scrollTo(options);
  }

  scrollToBottom(): void {
    this.logger.trace(this, 'Scroll To Bottom');
    const options = {bottom: -100, duration: 250};
    this.scrollbarRef.scrollTo(options);
  }

  scrollToIndex(index: number): void {
    index--;
    const row = this.rows.find(r => r.element.nativeElement.rowIndex === index);
    if (row) {
      const options = {duration: 250}; // TODO get options into scroll call.
      row.element.nativeElement.scrollIntoView(true);
    } else {
      console.log('Row at index ' + (index) + ' not found');
    }
  }

  // TODO return index more reliable. This sometimes fails to scroll (when changing the sorting and adding a new row).
  //  Add method that scrolls to entity passed.
  getLastRowIndex(): number {
    const row = this.rows.get(this.rows.length - 1);
    if (row) {
      return row.element.nativeElement.sectionRowIndex;
    } else {
      return 0;
    }
  }

  updateFilter(event: any): void {
    this.logger.trace(this, 'Filter Changed');
    this.filterEvent = event;
    this.tableDataSource.filter = JSON.stringify(event);
  }
}

