import { Scope, DynamicScope, Environment } from '../environment';
import { DestroyableBounds, clear, move as moveBounds } from '../bounds';
import { ElementStack, Tracker, UpdatableTracker } from '../builder';
import { LOGGER, Opaque, Stack, LinkedList, Dict, dict } from 'glimmer-util';
import {
  ConstReference,
  PathReference,
  IterationArtifacts,
  IteratorSynchronizer,
  IteratorSynchronizerDelegate,

  // Tags
  combine,
  Revision,
  UpdatableTag,
  combineSlice,
  CONSTANT_TAG,
  INITIAL
} from 'glimmer-reference';
import { EvaluatedArgs } from '../compiled/expressions/args';
import { OpcodeJSON, OpSeq, UpdatingOpcode, UpdatingOpSeq } from '../opcodes';
import { LabelOpcode } from '../compiled/opcodes/vm';
import { DOMChanges } from '../dom/helper';
import * as Simple from '../dom/interfaces';
import { CapturedFrame } from './frame';

import VM from './append';

export default class UpdatingVM {
  public env: Environment;
  public dom: DOMChanges;
  public alwaysRevalidate: boolean;
  private frameStack: Stack<UpdatingVMFrame> = new Stack<UpdatingVMFrame>();

  constructor(env: Environment, { alwaysRevalidate = false }) {
    this.env = env;
    this.dom = env.getDOM();
    this.alwaysRevalidate = alwaysRevalidate;
  }

  execute(opcodes: UpdatingOpSeq, handler: ExceptionHandler) {
    let { frameStack } = this;

    this.try(opcodes, handler);

    while (true) {
      if (frameStack.isEmpty()) break;

      let opcode = this.frameStack.current.nextStatement();

      if (opcode === null) {
        this.frameStack.pop();
        continue;
      }

      LOGGER.debug(`[VM] OP ${opcode.type}`);
      LOGGER.trace(opcode);

      opcode.evaluate(this);
    }
  }

  goto(op: UpdatingOpcode) {
    this.frameStack.current.goto(op);
  }

  try(ops: UpdatingOpSeq, handler: ExceptionHandler) {
    this.frameStack.push(new UpdatingVMFrame(this, ops, handler));
  }

  throw() {
    this.frameStack.current.handleException();
    this.frameStack.pop();
  }

  evaluateOpcode(opcode: UpdatingOpcode) {
    opcode.evaluate(this);
  }
}

export interface ExceptionHandler {
  handleException();
}

export interface VMState {
  env: Environment;
  scope: Scope;
  dynamicScope: DynamicScope;
  frame: CapturedFrame;
}

export abstract class BlockOpcode extends UpdatingOpcode implements DestroyableBounds {
  public type = "block";
  public next = null;
  public prev = null;

  protected env: Environment;
  protected scope: Scope;
  protected dynamicScope: DynamicScope;
  protected frame: CapturedFrame;
  protected children: LinkedList<UpdatingOpcode>;
  protected bounds: DestroyableBounds;
  public ops: OpSeq;

  constructor(ops: OpSeq, state: VMState, bounds: DestroyableBounds, children: LinkedList<UpdatingOpcode>) {
    super();
    let { env, scope, dynamicScope, frame } = state;
    this.ops = ops;
    this.children = children;
    this.env = env;
    this.scope = scope;
    this.dynamicScope = dynamicScope;
    this.frame = frame;
    this.bounds = bounds;
  }

  abstract didInitializeChildren();

  parentElement() {
    return this.bounds.parentElement();
  }

  firstNode() {
    return this.bounds.firstNode();
  }

  lastNode() {
    return this.bounds.lastNode();
  }

  evaluate(vm: UpdatingVM) {
    vm.try(this.children, null);
  }

  destroy() {
    this.bounds.destroy();
  }

  didDestroy() {
    this.env.didDestroy(this.bounds);
  }

  toJSON() : OpcodeJSON {
    let begin = this.ops.head() as LabelOpcode;
    let end = this.ops.tail() as LabelOpcode;
    let details = dict<string>();

    details["guid"] = `${this._guid}`;
    details["begin"] = begin.inspect();
    details["end"] = end.inspect();

    return {
      guid: this._guid,
      type: this.type,
      details,
      children: this.children.toArray().map(op => op.toJSON())
    };
  }
}

export class TryOpcode extends BlockOpcode implements ExceptionHandler {
  public type = "try";

  private _tag: UpdatableTag;

  protected bounds: UpdatableTracker;

  constructor(ops: OpSeq, state: VMState, bounds: UpdatableTracker, children: LinkedList<UpdatingOpcode>) {
    super(ops, state, bounds, children);
    this.tag = this._tag = new UpdatableTag(CONSTANT_TAG);
  }

  didInitializeChildren() {
    this._tag.update(combineSlice(this.children));
  }

  evaluate(vm: UpdatingVM) {
    vm.try(this.children, this);
  }

  handleException() {
    let { env, scope, ops, dynamicScope, frame } = this;

    let elementStack = ElementStack.resume(
      this.env,
      this.bounds,
      this.bounds.reset(env)
    );

    let vm = new VM(env, scope, dynamicScope, elementStack);
    let result = vm.resume(ops, frame);

    this.children = result.opcodes();
    this.didInitializeChildren();
  }

  toJSON() : OpcodeJSON {
    let json = super.toJSON();
    let begin = this.ops.head() as LabelOpcode;
    let end = this.ops.tail() as LabelOpcode;

    json["details"]["begin"] = JSON.stringify(begin.inspect());
    json["details"]["end"] = JSON.stringify(end.inspect());

    return super.toJSON();
  }
}

class ListRevalidationDelegate implements IteratorSynchronizerDelegate {
  private map: Dict<BlockOpcode>;
  private updating: LinkedList<UpdatingOpcode>;

  private didInsert = false;
  private didDelete = false;

  constructor(private opcode: ListBlockOpcode, private marker: Simple.Comment) {
    this.map = opcode.map;
    this.updating = opcode['children'];
  }

  insert(key: string, item: PathReference<Opaque>, memo: PathReference<Opaque>, before: string) {
    let { map, opcode, updating } = this;
    let nextSibling: Simple.Node = null;
    let reference = null;

    if (before) {
      reference = map[before];
      nextSibling = reference['bounds'].firstNode();
    } else {
      nextSibling = this.marker;
    }

    let vm = opcode.vmForInsertion(nextSibling);
    let tryOpcode: TryOpcode;

    vm.execute(opcode.ops, vm => {
      vm.frame.setArgs(EvaluatedArgs.positional([item, memo]));
      vm.frame.setOperand(item);
      vm.frame.setCondition(new ConstReference(true));
      vm.frame.setKey(key);

      let state = vm.capture();
      let tracker = vm.stack().pushUpdatableBlock();

      tryOpcode = new TryOpcode(opcode.ops, state, tracker, vm.updatingOpcodeStack.current);
    });

    tryOpcode.didInitializeChildren();

    updating.insertBefore(tryOpcode, reference);

    map[key] = tryOpcode;

    this.didInsert = true;
  }

  retain(key: string, item: PathReference<Opaque>, memo: PathReference<Opaque>) {
  }

  move(key: string, item: PathReference<Opaque>, memo: PathReference<Opaque>, before: string) {
    let { map, updating } = this;

    let entry = map[key];
    let reference = map[before] || null;

    if (before) {
      moveBounds(entry, reference.firstNode());
    } else {
      moveBounds(entry, this.marker);
    }

    updating.remove(entry);
    updating.insertBefore(entry, reference);
  }

  delete(key: string) {
    let { map } = this;
    let opcode = map[key];
    opcode.didDestroy();
    clear(opcode);
    this.updating.remove(opcode);
    delete map[key];

    this.didDelete = true;
  }

  done() {
    this.opcode.didInitializeChildren(this.didInsert || this.didDelete);
  }
}

export class ListBlockOpcode extends BlockOpcode {
  public type = "list-block";
  public map = dict<BlockOpcode>();
  public artifacts: IterationArtifacts;

  private lastIterated: Revision = INITIAL;
  private _tag: UpdatableTag;

  constructor(ops: OpSeq, state: VMState, bounds: Tracker, children: LinkedList<UpdatingOpcode>, artifacts: IterationArtifacts) {
    super(ops, state, bounds, children);
    this.artifacts = artifacts;
    let _tag = this._tag = new UpdatableTag(CONSTANT_TAG);
    this.tag = combine([artifacts.tag, _tag]);
  }

  didInitializeChildren(listDidChange = true) {
    this.lastIterated = this.artifacts.tag.value();

    if (listDidChange) {
      this._tag.update(combineSlice(this.children));
    }
  }

  evaluate(vm: UpdatingVM) {
    let { artifacts, lastIterated } = this;

    if (!artifacts.tag.validate(lastIterated)) {
      let { bounds } = this;
      let { dom } = vm;

      let marker = dom.createComment('');
      dom.insertAfter(bounds.parentElement(), marker, bounds.lastNode());

      let target = new ListRevalidationDelegate(this, marker);
      let synchronizer = new IteratorSynchronizer({ target, artifacts });

      synchronizer.sync();

      this.parentElement().removeChild(marker);
    }

    // Run now-updated updating opcodes
    super.evaluate(vm);
  }

  vmForInsertion(nextSibling: Simple.Node) {
    let { env, scope, dynamicScope } = this;

    let elementStack = ElementStack.forInitialRender(
      this.env,
      this.bounds.parentElement(),
      nextSibling
    );

    return new VM(env, scope, dynamicScope, elementStack);
  }

  toJSON() : OpcodeJSON {
    let json = super.toJSON();
    let map = this.map;

    let inner = Object.keys(map).map(key => {
      return `${JSON.stringify(key)}: ${map[key]._guid}`;
    }).join(", ");

    json["details"]["map"] = `{${inner}}`;

    return json;
  }
}

class UpdatingVMFrame {
  private vm: UpdatingVM;
  private ops: UpdatingOpSeq;
  private current: UpdatingOpcode;
  private exceptionHandler: ExceptionHandler;

  constructor(vm: UpdatingVM, ops: UpdatingOpSeq, handler: ExceptionHandler) {
    this.vm = vm;
    this.ops = ops;
    this.current = ops.head();
    this.exceptionHandler = handler;
  }

  goto(op: UpdatingOpcode) {
    this.current = op;
  }

  nextStatement(): UpdatingOpcode {
    let { current, ops } = this;
    if (current) this.current = ops.nextNode(current);
    return current;
  }

  handleException() {
    this.exceptionHandler.handleException();
  }
}

import { join as joinPath } from 'path';
import { AbiRepositoryConfig } from '../config';
import { RawLogResponse } from '../eth/responses';
import { createModuleDebug, TRACE_ENABLED } from '../utils/debug';
import { ManagedResource } from '../utils/resource';
import {
    decodeBestMatchingFunctionCall,
    decodeBestMatchingLogEvent,
    DecodedFunctionCall,
    DecodedLogEvent,
} from './decode';
import { loadAbiFile, loadSignatureFile, searchAbiFiles } from './files';
import { AbiItemDefinition } from './item';
import { computeSignature, computeSignatureHash } from './signature';

const { warn, debug, info, trace } = createModuleDebug('abi:repo');

interface AbiMatch {
    anonymous: boolean;
    candidates: AbiItemDefinition[];
}

interface AbiMatchParams {
    contractFingerprint?: string;
    contractAddress?: string;
}

export interface ContractAbi {
    contractName: string;
    fileName?: string;
}

/** Sort abi defintions in consistent priority order */
export function sortAbis(abis: AbiItemDefinition[]): AbiItemDefinition[] {
    if (abis.length > 1) {
        const sortedAbis = [...abis];
        sortedAbis.sort((a, b) => {
            // Always prefer user-supplied abis with an contract address attached
            const aHasAddress = a.contractAddress != null;
            const bHasAddress = b.contractAddress != null;
            if (aHasAddress !== bHasAddress) {
                return aHasAddress ? -1 : 1;
            }
            // Prefer user-supplied abi
            const aHasFingerprint = a.contractFingerprint != null;
            const bHasFingerprint = b.contractFingerprint != null;
            if (aHasFingerprint !== bHasFingerprint) {
                return aHasFingerprint ? -1 : 1;
            }
            return (
                // Prefer abis with shorter function name as longer ones
                // are sometimes used to deliberately produce signature hash
                // collisions
                a.name.length - b.name.length ||
                // Prefer abis with fewer parameters
                a.inputs.length - b.inputs.length ||
                // Sort the rest by name
                a.name.localeCompare(b.name) ||
                // Last restort is to string compare the full signature
                computeSignature(a).localeCompare(computeSignature(b))
            );
        });
        return sortedAbis;
    }
    return abis;
}

export class AbiRepository implements ManagedResource {
    private signatures: Map<string, AbiItemDefinition[]> = new Map();
    private contractsByFingerprint: Map<string, ContractAbi> = new Map();
    private contractsByAddress: Map<string, ContractAbi> = new Map();

    constructor(private config: AbiRepositoryConfig) {}

    private addToSignatures(sig: string, abis: AbiItemDefinition[]) {
        const match = this.signatures.get(sig);
        this.signatures.set(sig, sortAbis(match == null ? abis : [...match, ...abis]));
    }

    public async initialize() {
        const config = this.config;
        if (config.directory != null) {
            const abiCount = await this.loadAbisFromDir(config.directory!, config);
            info('Loaded %d ABIs from directory %s', abiCount, config.directory);
        }

        if (config.decodeAnonymous) {
            const fnCount = await this.loadAnonymousSignatures(joinPath(__dirname, '../../data/fns.abisigs.gz'));
            const evCount = await this.loadAnonymousSignatures(joinPath(__dirname, '../../data/evts.abisigs.gz'));
            info('Loaded %d anonymous ABI signatures from built-in signature files', fnCount + evCount);
        }
    }

    public async loadAnonymousSignatures(file: string): Promise<number> {
        debug('Loading anonymous signatures from %s', file);
        let count = 0;
        const { entries } = await loadSignatureFile(file);
        for (const [sig, abis] of entries) {
            this.addToSignatures(sig, abis);
            count++;
        }
        return count;
    }

    public async loadAbisFromDir(dir: string, config: AbiRepositoryConfig): Promise<number> {
        let count = 0;
        for await (const abiFile of searchAbiFiles(dir, config)) {
            await this.loadAbiFile(abiFile, config);
            count++;
        }
        return count;
    }

    public async loadAbiFile(path: string, config: AbiRepositoryConfig) {
        const abiFileContents = await loadAbiFile(path, config);
        const contractInfo: ContractAbi = {
            contractName: abiFileContents.contractName,
            fileName: abiFileContents.fileName,
        };
        if (abiFileContents.contractAddress != null) {
            this.contractsByAddress.set(abiFileContents.contractAddress.toLowerCase(), contractInfo);
        }
        if (abiFileContents.contractFingerprint != null) {
            if (this.contractsByFingerprint.has(abiFileContents.contractFingerprint)) {
                warn(
                    'Duplicate contract fingerprint for contracts %o and %o',
                    contractInfo,
                    this.contractsByFingerprint.get(abiFileContents.contractFingerprint)
                );
            } else {
                this.contractsByFingerprint.set(abiFileContents.contractFingerprint, contractInfo);
            }
        }

        for (const { sig, abi } of abiFileContents.entries) {
            const signatureHash = computeSignatureHash(sig, abi.type);
            this.addToSignatures(signatureHash, [abi]);
        }
    }

    public get signatureCount(): number {
        return this.signatures.size;
    }

    public getMatchingAbi(signatureHash: string): AbiMatch | undefined {
        const candidates = this.signatures.get(signatureHash);
        return candidates != null ? { anonymous: true, candidates } : undefined;
    }

    public getMatchingSignatureName(signatureHash: string): string | undefined {
        const candidates = this.signatures.get(signatureHash);
        trace(
            'getMatchingSignatureName(%o) --> ',
            signatureHash,
            candidates?.map(c => computeSignature(c))
        );
        if (candidates != null) {
            // We only want to consider signatures from contracts in our repo
            // that already have a fingerprint
            const filtered = candidates.filter(c => c.contractFingerprint != null);
            const signatures = new Set<string>(filtered.map(c => computeSignature(c)));
            if (signatures.size > 1) {
                throw new Error(`Multiple signatures (${[...signatures].join(', ')}) for sig hash ${signatureHash}`);
            }
            if (filtered.length > 0) {
                return computeSignature(filtered[0]);
            }
        }
    }

    public getContractByFingerprint(fingerprint: string): ContractAbi | undefined {
        return this.contractsByFingerprint.get(fingerprint);
    }

    public getContractByAddress(address: string): ContractAbi | undefined {
        return this.contractsByAddress.get(address?.toLowerCase());
    }

    public findMatchingAbis(
        sigHash: string,
        { contractFingerprint, contractAddress }: AbiMatchParams
    ): AbiMatch | undefined {
        const match = this.signatures.get(sigHash);
        if (match != null) {
            trace(
                'Looking for contract match %o for signature hash %s; candidates: %O',
                { contractAddress, contractFingerprint },
                sigHash,
                match.map(item => ({
                    name: item.contractName,
                    signature: computeSignature(item),
                    address: item.contractAddress,
                    fingerprint: item.contractFingerprint,
                }))
            );
            if (contractAddress != null) {
                const addressMatch = match.find(c => c.contractAddress === contractAddress.toLowerCase());
                if (addressMatch != null) {
                    return { candidates: [addressMatch], anonymous: false };
                }
            }
            if (contractFingerprint != null) {
                const fingerprintMatch = match.filter(c => c.contractFingerprint === contractFingerprint);
                if (fingerprintMatch.length > 0) {
                    return { candidates: fingerprintMatch, anonymous: false };
                }
            }
            if (match.length > 0) {
                return { candidates: match, anonymous: true };
            }
            if (TRACE_ENABLED) {
                trace(
                    'No matching contract found for method signature hash %s and contract fingerprint %s',
                    sigHash,
                    contractFingerprint
                );
            }
        }
        return { candidates: [], anonymous: true };
    }

    private abiDecode<T>(
        sigHash: string,
        matchParams: AbiMatchParams,
        decodeFn: (abis: AbiItemDefinition[], anonymous: boolean) => T
    ): T | undefined {
        const matchingAbis = this.findMatchingAbis(sigHash, matchParams);
        trace('Found %d matching ABIs for signature %s', matchingAbis?.candidates?.length ?? 0, sigHash);

        if (matchingAbis != null) {
            if (matchingAbis.anonymous && !this.config.decodeAnonymous) {
                return;
            }
            if (matchingAbis.candidates.length === 0) {
                trace('No matching ABI found for signature hash %s', sigHash);
                return;
            }
            try {
                return decodeFn(matchingAbis.candidates, matchingAbis!.anonymous);
            } catch (e) {
                if (matchingAbis!.anonymous) {
                    debug('Failed to decode anonymous ABI', e);
                } else {
                    warn('Failed to decode ABI', e);
                }
            }
        }
    }

    public decodeFunctionCall(data: string, matchParams: AbiMatchParams): DecodedFunctionCall | undefined {
        const sigHash = data.slice(2, 10);
        return this.abiDecode(sigHash, matchParams, (abi, anon) => decodeBestMatchingFunctionCall(data, abi, anon));
    }

    public decodeLogEvent(logEvent: RawLogResponse, matchParams: AbiMatchParams): DecodedLogEvent | undefined {
        if (!Array.isArray(logEvent.topics) || logEvent.topics.length === 0) {
            if (TRACE_ENABLED) {
                trace(
                    'No topics in log event tx=%s idx=%s - nothing to decode',
                    logEvent.transactionHash,
                    logEvent.logIndex
                );
            }
            return;
        }
        const sigHash = logEvent.topics[0].slice(2);
        const { data, topics } = logEvent;

        return this.abiDecode(sigHash, matchParams, (abi, anon) => decodeBestMatchingLogEvent(data, topics, abi, anon));
    }

    public async shutdown() {
        this.signatures.clear();
    }
}

import axios from 'axios';
import * as _ from 'lodash';

import { Log } from './log';

const log = new Log('ExistClient');

const baseUrl = 'https://exist.io/api/1/';

class ExistClient {
  public async getUserData(accessToken: string): Promise<any> {
    return await this.sendRequest('users/$self/today', accessToken);
  }

  public async acquireAttribute(accessToken: string, attributeName: string, active: boolean = true): Promise<void> {
    return await this.sendRequest('attributes/acquire/', accessToken, [{ name: attributeName, active }]);
  }

  public async tagPaychecks(accessToken: string, dates: string[]): Promise<any> {
    return await this.tagDates(accessToken, _.map(dates, (date) => ({ date, value: 'paycheck_received' })));
  }

  public async tagDates(accessToken: string, tags: ExistClient.ITag[]): Promise<any> {
    return await this.sendRequest('attributes/custom/append/', accessToken, tags);
  }

  public async updateMoneySpent(
    accessToken: string,
    attributeParams: ExistClient.INumericUserAttributeValue[],
  ): Promise<void> {
    // Make sure we have control of the attribute first.
    await this.acquireAttribute(accessToken, 'money_spent');

    const attributes: ExistClient.IUserAttribute[] = attributeParams.map((attribute) => {
      return { ...attribute, name: 'money_spent' };
    });

    return await this.sendRequest('attributes/update/', accessToken, attributes);
  }

  private async sendRequest(url: string, accessToken: string, data?: any): Promise<any> {
    const options = {
      data,
      headers: {
        Accept: 'application/json',
