import { users } from '@oada/lib-arangodb';
import { Requester } from '@oada/lib-kafka';

import config from './config';
import type { UserRequest, UserResponse } from './server';

import chalk from 'chalk';
import debug from 'debug';
import minimist from 'minimist';
import promptly from 'promptly';

const argv = minimist(process.argv.slice(2));

const trace = debug('useradd:trace');

async function findUserByUsername(username: string) {
  const like = await users.like({ username });
  for await (const user of like) {
    trace(user, 'findUserByUsername: Finished users.like');
    return user;
  }
  return false;
}

// The main event:
async function run() {
  try {
    if (argv.h || argv.help) {
      console.log(
        chalk.yellow(
          'useradd [-u username] [-p password] [ -a (if you want user to have admin priviledges to create other users)]'
        )
      );
      return;
    }

    //-------------------------------------
    // Talk to user service over Kafka...
    trace('Creating kafka requester...');
    // Produce a request to the user service to create one for us:
    const kafkareq = new Requester({
      // Topic to look for final answer on (consume):
      consumeTopic: config.get('kafka.topics.httpResponse'),
      // Topic to send request on (produce):
      produceTopic: config.get('kafka.topics.userRequest'),
      // group name
      group: 'useradd',
    });

    //-----------------------------------------------------
    // Ensure we have a username and password...
    const username = (argv.u ||
      argv.username ||
      (await promptly.prompt('Username: '))) as string;
    if (await findUserByUsername(username)) {
      console.error(chalk.red('Username ' + username + ' already exists'));
      process.exit(1);
    }
    const password = (argv.p ||
      argv.password ||
      (await promptly.prompt('Password: '))) as string;
    const isadmin = !!(argv.a || argv.isadmin || argv.isAdmin);

    trace('Sending request to kafka');
    const response = (await kafkareq.send({
      connection_id: 'useradd',
      token: '<PASSWORD>',
      authorization: {
        scope: ['oada.admin.user:all'],
      },
      // the "user" key is what goes into the DB
      user: {
        username,
        password,
        // Add scope if you want the user to have permission to create other users
        scope: isadmin ? ['oada.admin.user:all'] : [],
      },
    } as UserRequest)) as unknown as UserResponse;

    trace('Finished kafka.send, have our response = %O', response);
    // no need to keep hearing messages
    trace('Disconnecting from kafka');
    await kafkareq.disconnect();

    trace('Checking response.code, response = %O', response);
    if (response.code !== 'success') {
      console.error(
        chalk.red(
          'FAILED TO RECEIVE SUCCESSFUL RESPONSE FROM USER SERVICE WHEN CREATING USER!'
        )
      );
      return;
    }

    // Now we have a user
    const su = response.user;
    console.info(
      chalk.green('User ') +
        chalk.cyan(su._id) +
        chalk.green(' now exists: ') +
        su?._id
    );
  } catch (err) {
    console.error(err);
    process.exit(1);
  }
  process.exit(0);
}

void run();

import React, { useEffect } from 'react';
import Editor, { EditorProps } from '@monaco-editor/react';
import Logger from 'js-logger';

import './JSONEditor.less';

export type JSONEditorProps = {
  value?: string;
  onChange?: (value: string) => void;
  editorProps?: EditorProps;
};

export const JSONEditor: React.FC<JSONEditorProps> = ({
  value,
  onChange,
  editorProps
}) => {
    const [currentValue, setCurrentValue] = React.useState<string>();

    const changeHandler = (value: string) => {
      try {
        const jsonObject = JSON.parse(value);
        onChange(jsonObject);
      } catch (error) {
        Logger.trace('JSON-Editor:', error);
      }
    };

    useEffect(() => {
      if (!value) {
        setCurrentValue(undefined);
      } else {
        try {
          const jsonString = JSON.stringify(value, null, 2);
          if (jsonString) {
            setCurrentValue(jsonString);
          }
        } catch (error) {
          Logger.trace('JSON-Editor:', error);
        }
      }
    }, [value]);

    return (
        <Editor
          className="json-editor"
          value={currentValue}
          onChange={changeHandler}
          defaultLanguage="json"
          {...editorProps}
        />
    );
}

export default JSONEditor;

import { LOGGER } from "targety-logger";
import { Objects } from "./utils";
import { Context } from "./common/interfaces";
import { Handler } from "./Handler";
import { Request } from "./handlers/request/Request";
import { LambdaProxyEvent } from "./handlers/request/LambdaProxyEvent";
import { Response } from "./handlers/request/Response";
import { ResponseBody } from "./handlers/request/ResponseBody";
import { GenericEvent } from "./handlers/event/GenericEvent";
import { GenericRequest, RequestType } from "./GenericRequest";
import { EventRequest } from "./handlers/event/EventRequest";
import { APIGatewayRequestAuthorizerEvent } from "aws-lambda";
import { LambdaAuthorizerRequest } from "./handlers/auth/LambdaAuthorizerRequest";

/**
 * Represents the LambdaEntryPoint abstract class
 */

export abstract class LambdaEntryPoint {
    public handler: Handler;
    public initPromise: Promise<Handler>;

    public constructor() {
        // pre-loading the handler, even when no request was made yet
        this.initPromise = this.initializeHandler();
    }

    /**
     * HeartBeatResponse can be used to keep the Lambda warm using Cloudwatch Events
     */
    private static heartBeatResponse(request: Request): ResponseBody {
        LOGGER.trace("Heartbeat function");
        // Disable cors because
        return Response.noContent(request, { cors: false, defaultHeaders: false }).send();
    }

    /**
     * Entrypoint for the Api Gateway Proxy event.
     */
    public async handle(
        event: LambdaProxyEvent | GenericEvent<unknown> | APIGatewayRequestAuthorizerEvent | {},
        context?: Context,
    ): Promise<unknown> {
        let finalRequest: GenericRequest;
        LOGGER.trace({ event, context, type: "REQUEST" }, "incoming request");

        if (context) {
            context.callbackWaitsForEmptyEventLoop = false;
        }

        try {
            if ((event as GenericEvent<unknown>).Records) {
                finalRequest = new EventRequest<GenericEvent<unknown>>(event as GenericEvent<unknown>);
            } else if ((event as APIGatewayRequestAuthorizerEvent).type === "REQUEST") {
                finalRequest = new LambdaAuthorizerRequest(event as APIGatewayRequestAuthorizerEvent);
            } else {
                const request = new Request(event as LambdaProxyEvent);
                finalRequest = request;
                if (Objects.isEmpty(event)) {
                    return LambdaEntryPoint.heartBeatResponse(request);
                }
            }
            return await this.handleRequest(finalRequest, context);
        } catch (e) {
            if (finalRequest?.isType(RequestType.REQUEST)) {
                LOGGER.error(e, "Error handling request");
                return Response.fromError(finalRequest as Request, e);
            }
            throw e;
        }
    }

    /**
     * initializeHandler is used for example to open a DB connection or set up Dependency Injection
     * @returns handler Handler exposes api endpoint methods
     */
    protected abstract initializeHandler(): Promise<Handler>;

    private async handleRequest(request: GenericRequest, context: Context): Promise<unknown> {
        if (!this.handler) {
            this.handler = await this.initPromise;
        }
        return this.handler.handle(request, context);
    }
}

import { parseLogRecords, byteArrayToBuffer, byteArrayFromBuffer, serializeMessage, serializeLogRecord, parseLogRecord, wholeSlice } from './AmbrosiaFormat'
import { ByteArray, Message, uint64 } from './AmbrosiaFormat'
import { MsgCountReplayableRPCBatch, MsgUpgradeService, MsgTakeBecomingPrimaryCheckpoint, MsgUpgradeTakeCheckpoint } from './AmbrosiaFormat'
import { MsgInitialMessage, MsgCheckpoint, MsgRPCBatch, MsgTakeCheckpoint, MsgAttachTo, MsgRPC } from './AmbrosiaFormat'

import net = require("net");

type AmbrosiaLogEntry = Buffer
type AmbrosiaCheckpoint = Buffer

class Ambrosia {
  public buf: ByteArray = new ByteArray([])
  public replaying: boolean = true
  public sendSocket: any

  constructor(
    public onLogEntry: (logEntry: AmbrosiaLogEntry) => void,
    public onBecomePrimary: () => void,
    public onCheckpoint: () => AmbrosiaCheckpoint,
    public onRestoreCheckpoint: (checkpoint: AmbrosiaCheckpoint) => void,
    public host: string = "127.0.0.1",
    public sendPort: number = 1000,
    public receivePort: number = 1001
  ) {
    // Open client for sending messages to the Immortal Coordinator.
    this.sendSocket = new net.Socket();

    this.sendSocket.connect(sendPort, host, () => {
      this.trace("Connected to: " + host + ":" + sendPort)
    })

    // Wait for incoming connection from the Immortal Coordinator.
    net.createServer((sock: any) => {
      this.trace("Connected to: " + sock.remoteAddress + ":" + sock.remotePort)

      // Handle received data.
      sock.on('data', (data: any) => {
        this.trace("Received data from IC: " + data.toString('hex'))

        // Transfer bytes into shared buffer until we have parseable message.
        var tmpBuffer : number[] = []

        for(const d of data.values()) {
          tmpBuffer.push(d)
        }

        this.buf.concat(new ByteArray(tmpBuffer))

        let accumulated : Message[] = []
        try {
          let logRecords = parseLogRecords(wholeSlice(this.buf))
          for(var logRecord of logRecords) {
            for(var msg of logRecord.msgs) {
              accumulated.push(msg)
            }
          }

          this.buf = new ByteArray([])
        } catch (err) {
          this.trace("Parsing error: " + err)
        }
        for(var msg of accumulated)
        {
          this.handle(msg)
        }
      });
    }).listen(receivePort, host)
  }

  handle(message: Message) {
    this.trace("Handle invoked for message type: " + message.typ)

    if(message instanceof MsgCountReplayableRPCBatch) {
      throw new Error("Not implemented!")
    } 
    else if(message instanceof MsgUpgradeService) {
      throw new Error("Not implemented!")
    }
    else if(message instanceof MsgTakeBecomingPrimaryCheckpoint) {
      // Disable replaying.
      this.replaying = false

      // Create initial RPC message.
      let rpcMessage = new MsgRPC()
      rpcMessage.methodId = 0
      rpcMessage.isOutgoing = false

      // Create initial message containing the initial RPC message.
      let initialMessage = new MsgInitialMessage()
      initialMessage.rpc = rpcMessage

      // Send initial message.
      this.sendBuffer(initialMessage)

      // Send checkpoint.
      let checkpointMessage = new MsgCheckpoint()
      checkpointMessage.checkpoint = byteArrayFromBuffer(this.onCheckpoint())
      this.sendBuffer(checkpointMessage)
    }
    else if(message instanceof MsgUpgradeTakeCheckpoint) {
      throw new Error("Not implemented!")
    }
    else if(message instanceof MsgInitialMessage) {
      // Nothing.
    } 
    else if(message instanceof MsgCheckpoint) {
      let buffer = byteArrayToBuffer(message.checkpoint)
      this.onRestoreCheckpoint(buffer)
    }
    else if(message instanceof MsgRPCBatch) {
      throw new Error("Not implemented!")
    } 
    else if(message instanceof MsgTakeCheckpoint) {
      // Send checkpoint.
      let checkpointMessage = new MsgCheckpoint()
      checkpointMessage.checkpoint = byteArrayFromBuffer(new Buffer(this.onCheckpoint()))
      this.sendBuffer(checkpointMessage)
    }
    else if(message instanceof MsgAttachTo) {
      throw new Error("Not implemented!")
    }
    else if(message instanceof MsgRPC) {
      // console.log("**** method: " + message.methodId)
      let logEntry = byteArrayToBuffer(message.serializedArgs)
      this.onLogEntry(logEntry)
    }
    else {
      throw new Error("Unknown message type!")
    }
  }

  isReplaying() {
      return this.replaying
  }

  selfRPC(logEntry: AmbrosiaLogEntry) {
    this.trace("selfRPC invoked")
    let message = new MsgRPC()
    message.methodId = 0
    message.isOutgoing = true
    message.isSelfCall = true
    message.serializedArgs = byteArrayFromBuffer(logEntry)
    this.sendBuffer(message)
  }

  sendBuffer(message: Message) {
    let serialized = serializeMessage(message)

    serialized.iterate((x: Buffer) => {
      this.trace("About to send buffer:")
      console.log(x)

      this.sendSocket.write(x, () => {
        this.trace("Transmitted buffer with type: " + message.typ + " and size: " + x.byteLength)
      })
    })
  }

  trace(message: string) {
    console.log("AMBROSIA LOG: " + message)
  }
}

export default Ambrosia

import * as s from "capnp-ts/src/std/schema.capnp.js";
import { format } from "capnp-ts/src/util";
import initTrace from "debug";

import { CodeGeneratorFileContext } from "./code-generator-file-context";
import { ConcreteListType } from "./constants";
import * as E from "./errors";
import * as util from "./util";

const trace = initTrace("capnpc:file");
trace("load");

export function compareCodeOrder(a: { getCodeOrder(): number }, b: { getCodeOrder(): number }): number {
  return a.getCodeOrder() - b.getCodeOrder();
}

export function getConcreteListType(ctx: CodeGeneratorFileContext, type: s.Type): string {
  if (!type.isList()) return getJsType(ctx, type, false);

  const elementType = type.getList().getElementType();
  const elementTypeWhich = elementType.which();

  if (elementTypeWhich === s.Type.LIST) {
    return `capnp.PointerList(${getConcreteListType(ctx, elementType)})`;
  } else if (elementTypeWhich === s.Type.STRUCT) {
    const structNode = lookupNode(ctx, elementType.getStruct().getTypeId());

    if (structNode.getStruct().getPreferredListEncoding() !== s.ElementSize.INLINE_COMPOSITE) {
      throw new Error(E.GEN_FIELD_NON_INLINE_STRUCT_LIST);
    }

    return `capnp.CompositeList(${getJsType(ctx, elementType, false)})`;
  }

  return ConcreteListType[elementTypeWhich];
}

export function getDisplayNamePrefix(node: s.Node): string {
  return node.getDisplayName().substr(node.getDisplayNamePrefixLength());
}

export function getFullClassName(node: s.Node): string {
  return node.getDisplayName().split(":")[1].split(".").map(util.c2t).join("_");
}

export function getJsType(ctx: CodeGeneratorFileContext, type: s.Type, constructor: boolean): string {
  const whichType = type.which();

  switch (whichType) {
    case s.Type.ANY_POINTER:
      return "capnp.Pointer";

    case s.Type.BOOL:
      return "boolean";

    case s.Type.DATA:
      return "capnp.Data";

    case s.Type.ENUM:
      return getFullClassName(lookupNode(ctx, type.getEnum().getTypeId()));

    case s.Type.FLOAT32:
    case s.Type.FLOAT64:
    case s.Type.INT16:
    case s.Type.INT32:
    case s.Type.INT8:
    case s.Type.UINT16:
    case s.Type.UINT32:
    case s.Type.UINT8:
      return "number";

    case s.Type.UINT64:
    case s.Type.INT64:
      return "bigint";

    case s.Type.INTERFACE:
      return "capnp.Interface";

    case s.Type.LIST:
      return `capnp.List${constructor ? "Ctor" : ""}<${getJsType(ctx, type.getList().getElementType(), false)}>`;

    case s.Type.STRUCT: {
      const c = getFullClassName(lookupNode(ctx, type.getStruct().getTypeId()));

      return constructor ? `capnp.StructCtor<${c}>` : c;
    }

    case s.Type.TEXT:
      return "string";

    case s.Type.VOID:
      return "capnp.Void";

    default:
      throw new Error(format(E.GEN_UNKNOWN_TYPE, whichType));
  }
}

export function getUnnamedUnionFields(node: s.Node): s.Field[] {
  if (!node.isStruct()) return [];

  return node
    .getStruct()
    .getFields()
    .filter((f) => f.getDiscriminantValue() !== s.Field.NO_DISCRIMINANT);
}

export function hasNode(ctx: CodeGeneratorFileContext, lookup: { getId(): bigint } | bigint): boolean {
  const id = typeof lookup === "bigint" ? lookup : lookup.getId();

  return ctx.nodes.some((n) => n.getId() === id);
}

export function loadRequestedFile(
  req: s.CodeGeneratorRequest,
  file: s.CodeGeneratorRequest_RequestedFile
): CodeGeneratorFileContext {
  trace("compile(%s, %s)", req, file);

  const ctx = new CodeGeneratorFileContext(req, file);

  const schema = lookupNode(ctx, file.getId());

  ctx.tsPath = schema.getDisplayName() + ".ts";

  return ctx;
}

export function lookupNode(ctx: CodeGeneratorFileContext, lookup: { getId(): bigint } | bigint): s.Node {
  const id = typeof lookup === "bigint" ? lookup : lookup.getId();
  const node = ctx.nodes.find((n) => n.getId() === id);

  if (node === undefined) throw new Error(format(E.GEN_NODE_LOOKUP_FAIL, id));

  return node;
}

/**
 * Determine whether the given field needs a concrete list class: this is currently the case for composite lists
 * (`capnp.CompositeList`) and lists of lists (`capnp.PointerList`).
 *
 * @param {s.Field} field The field to check.
 * @returns {boolean} Returns `true` if the field requires a concrete list class initializer.
 */

export function needsConcreteListClass(field: s.Field): boolean {
  if (!field.isSlot()) return false;

  const slotType = field.getSlot().getType();

  if (!slotType.isList()) return false;

  const elementType = slotType.getList().getElementType();

  return elementType.isStruct() || elementType.isList();
}

import * as vscode from 'vscode';
import { CommentManager, DComment, DThread } from './comment';
import { DocumentFinder } from './document';
import { parseDanmaku, TextDanmaku } from './danmaku';
import { OutputTerminal } from './terminal';
import { formatHMS } from './utils';
import { Backend } from './backend';

export class Danmacom implements vscode.CodeLensProvider {
    commentController: vscode.CommentController;
    commentManager: CommentManager;
    documentFinder: DocumentFinder;
    disposables: vscode.Disposable[];
    running: boolean;
    unread: number;
    status: vscode.StatusBarItem;

    codeLensesEmitter: vscode.EventEmitter<void>;
    onDidChangeCodeLenses: vscode.Event<void>;

    constructor(
        public outputTerminal: OutputTerminal,
        public terminal: vscode.Terminal,
        public backend: Backend
    ) {
        this.commentController =
            vscode.comments.createCommentController('danmacom', 'Danmacom');
        this.commentManager = new CommentManager(this.commentController);
        this.documentFinder = new DocumentFinder;
        this.running = true;
        this.unread = 0;

        this.status = vscode.window.createStatusBarItem(
            vscode.StatusBarAlignment.Right,
            100
        );

        this.status.tooltip = 'Danmacom - Click to show terminal'
        this.status.command = 'danmacom.statusBar';
        this.updateStatus();
        this.status.show();

        this.codeLensesEmitter = new vscode.EventEmitter();
        this.onDidChangeCodeLenses = this.codeLensesEmitter.event;

        this.disposables = [
            this.commentController,
            this.backend,
            this.commentManager,
            this.documentFinder,
            this.status,
            this.codeLensesEmitter,

            vscode.languages.registerCodeLensProvider(
                { scheme: 'file' },
                this
            ),

            vscode.window.onDidChangeActiveTerminal((term) => {
                if (term === this.terminal) {
                    this.unread = 0;
                    this.updateStatus();
                }
            }),

            this.commentManager.onCommentChange(() => {
                this.codeLensesEmitter.fire();
            }),

            this.backend.onLogMessage(data => {
                if (! data.endsWith('\n')) data += '\n';
                this.printRGB(data.replace(/\n/g, '\r\n'), [128, 128, 128])
            }),

            this.backend.onDanmaku(this.handleLine.bind(this)),
            this.backend.onClose(this.dispose.bind(this)),

            this.outputTerminal.onClose(this.dispose.bind(this)),
            this.outputTerminal.onInput((data) => {
                if (data === '\x03') {
                    this.error('Interrupted');
                    this.dispose();
                } else if (data === '\r' || data === ' ') {
                    this.unread = 0;
                    this.updateStatus();
                }
            })
        ];

        this.trace(`[Starting: ${backend}]`);
        terminal.show();
    }

    clickStatusBar() {
        this.terminal.show();
        this.unread = 0;
        this.updateStatus();
    }

    updateStatus() {
        this.status.text = '$(comment-discussion)$(arrow-right)$(file-code)';
        if (this.unread > 0)
            this.status.text += ` ($(bell)${this.unread})`;
    }

    handleReply(reply: vscode.CommentReply) {
        const text = reply.text.trim();
        const thread =
            ('refId' in reply.thread)
            ? (reply.thread as DThread)
            : this.commentManager.addThread(reply.thread);

        const comment = new DComment(
            'Host', null, text, thread, this.commentManager
        );

        this.trace(`[${formatHMS(comment.date)}] [Host]: /${thread.refId} ${text}`);
        this.codeLensesEmitter.fire();
    }

    provideCodeLenses(
        document: vscode.TextDocument,
        token: vscode.CancellationToken
    ): vscode.CodeLens[] {
        return this.commentManager.listThreads(document.uri)
            .map(thread => {
                const pre = thread.line === null ? 'File: ' : '';

                return new vscode.CodeLens(thread.range, {
                    title: `${pre}/${thread.refId}: ${thread.comments.length} comment(s)`,
                    command: 'danmacom.showThread',
                    arguments: [thread],
                });
            })
    }

    resolveCodeLens(
        codeLens: vscode.CodeLens,
        _token: vscode.CancellationToken
    ): vscode.CodeLens {
        return codeLens;
    }

    handleLine(json: TextDanmaku) {
        const danmaku = parseDanmaku(json);
        if (danmaku === null) {
            this.error(`  -> Error: Cannot parse json: ${json}`);
            return;
        }

        this.trace(`[${formatHMS(new Date())}] ${danmaku.author}: ${danmaku.content}`);

        if (danmaku.type === 'thread') {
            const threadResult =
                this.commentManager.getThreadById(danmaku.thread)

            if (threadResult.type === 'error') {
                this.error(`  -> Error: ${threadResult.message}`);
            } else {
                new DComment(
                    danmaku.author, danmaku.face, danmaku.text,
                    threadResult.thread, this.commentManager
                );
            }
        } else if (danmaku.type === 'file') {
            const danmaku_lower = danmaku.file.toLowerCase();
            const pred: { [k: string]: (s: string) => boolean } = {
                '/': (s) => s.toLowerCase().indexOf(danmaku_lower) !== -1,
                '^': (s) => s.toLowerCase().startsWith(danmaku_lower),
                '$': (s) => s.toLowerCase().endsWith(danmaku_lower),
                '=': (s) => s === danmaku.file
            };
            const uriResult =
                this.documentFinder.findDocument(pred[danmaku.leader]);

            if (uriResult.type === 'not_found') {
                this.error(`  -> Error: ${JSON.stringify(danmaku.file)} not found`)
            } else if (uriResult.type === 'multiple_found') {
                this.error(`  -> Error: ${JSON.stringify(danmaku.file)} is ambiguous: ${uriResult.paths.join(', ')}`)
            } else if (danmaku.line
                && (danmaku.line < 0
                    || danmaku.line >= uriResult.result.lineCount)) {
                this.error(`  -> Error: Line number ${danmaku.line + 1} out of range`);
            } else {
                const thread =
                    this.commentManager.getThread(
                        uriResult.result.uri, danmaku.line ?? null);

                new DComment(
                    danmaku.author, danmaku.face, danmaku.text,
                    thread, this.commentManager
                );
                this.trace(`  -> Thread id is ${thread.refId}, reply using '/${thread.refId} comment'`)
            }
        }

        this.codeLensesEmitter.fire();

        this.unread ++;
        this.updateStatus();
    }

    printRGB(data: string, [r, g, b]: [number, number, number]) {
        this.outputTerminal.write(
            `\x1b[38;2;${r};${g};${b}m${data}\x1b[0m`
        )
    }

    error(line: string) {
        this.printRGB(line + '\r\n', [255, 0, 0]);
    }

    notice(line: string) {
        this.printRGB(line + '\r\n', [0, 0, 255]);
    }

    trace(line: string) {
        this.printRGB(line + '\r\n', [0, 0, 0]);
    }

    dispose() {
        this.trace('[Stopping]');

        if (this.running) {
            this.running = false;
            this.disposables.forEach(x => x.dispose());
        }
    }
}

