            this.video = "choose"
          }
          else {
            this.video = dataJson.Config.Volume * 100
          }
          if ((dataJson.Config.MicVolume) == null) {
            this.microphone = "choose"
          }
          else {
            this.microphone = dataJson.Config.MicVolume
          }
          this.CaptureWidth = dataJson.Config.CaptureWidth;
