    //       ['2018', 1, 5, 3],
    //       ['2019', 3, 2, 2.5],
    //       ['2020', 3, 9, 6],
    //     ];
    //     break;
    // }
  }

  fnGetDataDashboardByPeriod(period, token) {
    const self = this;
    self.loading_state = true;
    self.data_results = {
      'hoy': 0,
      'totalPendientes': 0,
