    .randomBytes(16)
    .toString('base64')
    .replace(/[/+=]/g, '')
    .slice(0, e)
}

function generateDS(salt: string) {
  const time = Math.floor(Date.now() / 1000)
  const random = randomString(6)

  const c = crypto
    .createHash('md5')
    .update(`salt=${salt}&t=${time}&r=${random}`)
    .digest('hex')
  return `${time},${random},${c}`
}

