  '/api/video/seek',
  [
    body('seekTime')
      .not()
      .isEmpty()
      .withMessage('Cant be empty')
      .isNumeric()
      .withMessage('Must be a number'),
  ],
  validateRequest,
  async (req: Request, res: Response) => {
    const { seekTime } = req.body;
    const response = videoPlayer.seekVideo(seekTime);
    res.send(response);
  }
);

export { router as seekVideoRouter };

