function escapeHtml(value: string): string {
    return value
      .replace(/&/g, '&amp;')
      .replace(/>/g, '&gt;')
      .replace(/</g, '&lt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;')
      .replace(/\//g, '&#x2F;')
      .replace(/\(/g, '&#x28;')
      .replace(/\)/g, '&#x29;');
  }

  export const notFoundHandler: Handler = (req, res) => {
    res.status(404).json(new LogicError(ErrorCode.NOT_FOUND, `Route ${escapeHtml(req.url)} is not found`));
