import { getCurrentHub } from '../packages/hub';
import { Event, Integration, Severity } from '../packages/types';
import {
  addExceptionMechanism,
  addInstrumentationHandler,
  getCurrentPageRoute,
  isPrimitive,
  logger,
} from '../packages/utils';

import { eventFromUnknownInput } from '../eventbuilder';
import { shouldIgnoreOnError } from '../helpers';

/** JSDoc */
interface GlobalHandlersIntegrations {
  onError: boolean;
  onUnhandledRejection: boolean;
}

/** Global handlers */
export class GlobalHandlers implements Integration {
  /**
   * @inheritDoc
   */
  public static id: string = 'GlobalHandlers';

  /**
   * @inheritDoc
   */
  public name: string = GlobalHandlers.id;

  /** JSDoc */
  private readonly _options: GlobalHandlersIntegrations;

  /** JSDoc */
  private _onErrorHandlerInstalled: boolean = false;

  /** JSDoc */
  private _onUnhandledRejectionHandlerInstalled: boolean = false;

  /** JSDoc */
  public constructor(options?: GlobalHandlersIntegrations) {
    this._options = {
      onError: true,
      onUnhandledRejection: true,
      ...options,
    };
  }
  /**
   * @inheritDoc
   */
  public setupOnce(): void {
    Error.stackTraceLimit = 50;

    if (this._options.onError) {
      if (__LOG__) {
        logger.log('Global Handler attached: onError');
      }
      this._installGlobalOnErrorHandler();
    }

    if (this._options.onUnhandledRejection) {
      if (__LOG__) {
        logger.log('Global Handler attached: onUnhandledRejection');
      }
      this._installGlobalOnUnhandledRejectionHandler();
    }
  }

  /** JSDoc */
  private _installGlobalOnErrorHandler(): void {
    if (this._onErrorHandlerInstalled) {
      return;
    }

    addInstrumentationHandler({
      callback: (data: { error: any }) => {
        const error = data.error;
        const currentHub = getCurrentHub();
        const hasIntegration = currentHub.getIntegration(GlobalHandlers);

        if (!hasIntegration || shouldIgnoreOnError()) {
          return;
        }

        const client = currentHub.getClient();
        const event = GlobalHandlers._enhanceEventWithInitialFrame(
          eventFromUnknownInput(error, undefined, {
            attachStacktrace: client && client.getOptions().attachStacktrace,
            rejection: false,
          }),
        );

        addExceptionMechanism(event, {
          handled: false,
          type: 'onError',
        });

        currentHub.captureEvent(event, {
          originalException: error,
        });
      },
      type: 'error',
    });

    this._onErrorHandlerInstalled = true;
  }

  /** JSDoc */
  private _installGlobalOnUnhandledRejectionHandler(): void {
    if (this._onUnhandledRejectionHandlerInstalled) {
      return;
    }

    addInstrumentationHandler({
      callback: (e: any) => {
        let error = e;

        // dig the object of the rejection out of known event types
        try {
          // PromiseRejectionEvents store the object of the rejection under 'reason'
          // see https://developer.mozilla.org/en-US/docs/Web/API/PromiseRejectionEvent
          if ('reason' in e) {
            error = e.reason;
          }
        } catch (_oO) {
          // no-empty
        }

        const currentHub = getCurrentHub();
        const hasIntegration = currentHub.getIntegration(GlobalHandlers);

        if (!hasIntegration || shouldIgnoreOnError()) {
          return true;
        }

        const client = currentHub.getClient();
        const event = isPrimitive(error)
          ? GlobalHandlers._eventFromIncompleteRejection(error)
          : eventFromUnknownInput(error, undefined, {
              attachStacktrace: client && client.getOptions().attachStacktrace,
              rejection: true,
            });

        event.level = Severity.Error;

        addExceptionMechanism(event, {
          handled: false,
          type: 'onUnhandledRejection',
        });

        currentHub.captureEvent(event, {
          originalException: error,
        });

        return;
      },
      type: 'unhandledRejection',
    });

    this._onUnhandledRejectionHandlerInstalled = true;
  }

  /**
   * This function creates an Event from an TraceKitStackTrace that has part of it missing.
   */
  private static _eventFromIncompleteRejection(error: any): Event {
    return {
      exception: {
        values: [
          {
            type: 'UnhandledRejection',
            value: `Promise rejection captured with value: ${error}`,
          },
        ],
      },
    };
  }

  /** JSDoc */
  private static _enhanceEventWithInitialFrame(event: Event): Event {
    event.exception ||= {};
    event.exception.values ||= [];
    event.exception.values[0] ||= {};
    event.exception.values[0].stacktrace ||= {};
    event.exception.values[0].stacktrace.frames ||= [];

    if (event.exception.values[0].stacktrace.frames.length === 0) {
      event.exception.values[0].stacktrace.frames.push({
        lineno: undefined,
        colno: undefined,
        filename: getCurrentPageRoute(),
        function: '?',
        in_app: true,
      });
    }

    return event;
  }
}

