                else {
                    var dateValue = date.getDate() + (new Date(year, date.getMonth(), 0, 12)).getDate();
                    dateIndex = Math.min(dateValue, dateSource(yearIndex, monthIndex).getLength()) - 1;
                }

                return {
                    year: yearIndex,
                    month: monthIndex,
                    date: dateIndex
                };
            },
