            }
            res.push(r)
        } else {
            for (let i of common.range(n)) {
                if (!used[i]) {
                    [used[i], buf[low]] = [true, arr[i]]
                    dfs(low + 1, n)
                    used[i] = false
                }
            }
        }
    }
    dfs()
    return res
}


/**
