}

/**
 * 无限循环队列
 * @param total 
 */
export function* cycleQueue(total:number):IterableIterator<number>{
    const queue = Array(total).fill(0).map((v,i)=>v=i)
    for(let i = 0;; i = (i+1)%total){
        yield queue[i]
    }
}

/**
 * 升序队列
 * @param total /0,1,2,3...,total-1/
 */
export function* asceQueue(total:number):IterableIterator<number>{
    let i = total
    while(total--){
        yield i-total-1
    }
}

/**
 * 降序队列
 * @param total /total-1,total-2,...,3,2,1,0/
 */
export function* descQueue(total:number):IterableIterator<number>{
    while(total--){
        yield total
    }
}

/**
 * 区间序列
 * @param from 起始位
 * @param to 目标位
 * @param step 步长
 */
export function* rangeIterator(from:number,to:number,step:number):IterableIterator<number>{
    let max = Math.max(from, to)
    if(max===from){
        while(from>=to){
            yield from
            from-=step
        }
    }else{
        while(from<=to){
            yield from
            from+=step
        }
    }
}

/**
 * 区间序列[from,to]
 * @param from 起始位
 * @param to 目标位
 * @param step 步长
 */
export function range(from:number,to:number,step:number=1):Array<number>{
    if(step<=0){
        throw Error("步长必须大于0")
    }
    let res:Array<number> = []
    let iter = rangeIterator(from,to,step)
    let n = iter.next()
    while(!n.done){
        res.push(n.value)
        n = iter.next()
    }
    return res
}

/**
* @notice 此处暂时只考虑方阵
* 高斯消元解线性方程组
* @param matricLeft 
* @param matricRight 
* @returns 
*/ 
 export function gaussSolutions(matricLeft:Array<Array<number>>,matricRight:Array<number>){
    let len = matricLeft.length
    let resolve = new Array(0)
    for(let i = 0 ; i < len ; i ++){
        //任取第i个元素不为0的行消元
        let diss = -1
        for(let s = 0 ; s < len ; s++){
            if(resolve.indexOf(s)==-1 && matricLeft[s][i]!=0){
                diss = s
                break
            } 
        }
        if(diss==-1){
            //非满秩，则无唯一解
            return null
        }
        resolve.push(diss)

        let coefficient = matricLeft[diss][i]
        //本身系数归一
        if(coefficient!=1){
            for(let j = 0 ; j < len ; j ++){
                matricLeft[diss][j] /=  coefficient
            }
            matricRight[diss] /= coefficient
        }

        for(let k = 0 ; k< len ; k++){
            if(matricLeft[k][i] == 0 || k==diss) continue
            //第k行消元
            let factor = -matricLeft[k][i]
            matricRight[k] += factor*matricRight[diss]
            for(let l = 0 ; l< len ; l++){
                matricLeft[k][l] += factor*matricLeft[diss][l]
            }
        }
    }        
    return resolve.map(v=>v=matricRight[v])
}

