      mkdir(folder, {recursive: true}, (err) => {
        if (err) {
          throw err;
        }
        cb(null, folder);
      });
    },
    filename: function (req, file, cb) {
      cb(null, file.originalname);
    }
  })
});

export {
  MULTER_UPLOAD
};

