    public logout$ = createEffect(() => this.actions.pipe(
        ofType(AuthActions.logout),
        tap(_ => {
            localStorage.removeItem(LocalStorageKeys.User);
            this.router.navigateByUrl('/');
        })
    ), { dispatch: false });
}

