import * as ko from "knockout";

import { UIMLWrapper } from "./uiml-wrapper";
import { IPart, htmlUiRendererPeers } from "./uiml";

function template(html: string): HTMLElement {
    var div = document.createElement("div");
    div.innerHTML = html;
    return div.children.length === 1 ? <HTMLElement>div.children[0] : div;
}

export interface IRenderer {
    render: (container?: HTMLElement) => HTMLElement;
    renderers: IRenderer[];
    getProperty: (propertyName: string) => any;
    part: IPart;
    renderChildren: (container: HTMLElement) => void;
}

export class InterfaceRenderer implements IRenderer {
    styles: any;
    part: IPart;
    constructor(part: IPart, uimlWrapper: UIMLWrapper) {
        this.part = part;
        this.styles = uimlWrapper.getStyles(part);
        (part.parts || []).forEach((partInfo) => {
            this.renderers.push(uimlWrapper.createRenderer(partInfo));
        });
    }
    getCustomProcessedStyles(): any {
        return ["cssClasses", "text", "data"]
    }
    applyStyles(part: IPart, element: HTMLElement) {
        Object.keys(this.styles).forEach(key => {
            var styleName = key;
            var styleValue = this.styles[key];
            if(this.getCustomProcessedStyles().indexOf(styleName) === -1) {
                (<any>element).css(styleName, styleValue);
            }
        });
        Object.keys(this.styles.cssClasses)
            .map(key => this.styles.cssClasses[key])
            .forEach(className => {
                element.className += (" " + className);
            });
        var text = this.getProperty("text");
        if(text && element.children.length === 0) {
            element.innerText = text;
        }
        var html = this.getProperty("html");
        if(html && element.children.length === 0) {
            element.innerHTML = html;
        }
    }
    getProperty(propertyName: string) {
        return this.part[propertyName] !== undefined ? this.part[propertyName] : this.styles[propertyName];
    }
    renderChildren(container: HTMLElement) {
        this.renderers.forEach(renderer => {
            renderer.render(container);
        });
    }
    getRenderResult() {
        return template("<div/>");
    }
    render(container: HTMLElement = null) {
        var renderResult = this.getRenderResult();
        var dataBindValue = this.getProperty("dataBind");
        if(dataBindValue !== undefined) {
            renderResult.dataset.bind = Object.keys(dataBindValue).map((k) => `${k}: ${dataBindValue[k]}`).join(", ");
        }
        this.applyStyles(this.part, renderResult);
        this.renderChildren(renderResult);
        var hint = this.getProperty("hint");
        if(!!hint) {
            renderResult.title = hint;
        }
        if(container) {
            container.append(renderResult);
        }
        return renderResult;
    }
    renderers: IRenderer[] = [];
}

export class ComponentRenderer extends InterfaceRenderer {
    public static componentPrefix = "";
    constructor(part: IPart, uimlWrapper: UIMLWrapper) {
        super(part, uimlWrapper);
    }
    render(container: HTMLElement) {
        var widgetName = ((ComponentRenderer.componentPrefix ? (ComponentRenderer.componentPrefix + "-") : "") + this.part.partclass).toLowerCase();
        var renderResult;
        var widgetOptions = JSON.stringify(this.part).split("\"").join("'");
        if(ko.components.isRegistered(widgetName)) {
            renderResult = template("<" + widgetName + " params=\"{ model: $data, context: $context, options: " + widgetOptions + "}\"/>");
        } else {
            if(typeof htmlUiRendererPeers[0].wloaders[widgetName] === "function") {
                renderResult = template("<div data-bind=\"lazyWidget: { name: '" + widgetName + "', options: " + widgetOptions + " }\"/>");
            } else {
                renderResult = template("<component-stub params=\"{ message: 'Error: Component " + widgetName + " is not installed.'}\"/>");
            }
        }
        this.applyStyles(this.part, renderResult);
        container.append(renderResult);
        return renderResult;
    }
}

ko.components.register("component-stub", {
    viewModel: {
        createViewModel: function(params, componentInfo) {
            return {
                message: params.message
            };
        }
    },
    template: "<div data-bind='text: message'></div>"
});

export class ContainerRenderer extends InterfaceRenderer {
    constructor(part: IPart, uimlWrapper: UIMLWrapper) {
        super(part, uimlWrapper);
    }
    getRenderResult() {
        var bindings: string[] = [];
        var visible = this.getProperty("visible");
        if(!!visible) {
            bindings.push("visible: " + visible);
        }
        var css = this.getProperty("css");
        if(!!css) {
            bindings.push("css: " + css);
        }
        var element = template("<div data-bind='" + bindings.join(", ")  + "'/>");
        return element;
    }
}

export class LabelRenderer extends InterfaceRenderer {
    constructor(part: IPart, uimlWrapper: UIMLWrapper) {
        super(part, uimlWrapper);
    }
    getRenderResult() {
        return template(`<label>${this.getProperty("text")}</label>`);
    }
}

export class InputRenderer extends InterfaceRenderer {
    constructor(part: IPart, uimlWrapper: UIMLWrapper) {
        super(part, uimlWrapper);
    }
    getRenderResult() {
        return template("<input class=\"input-control\" placeholder=\"" + (this.getProperty("pleceholderText")||"") + "\""
            + " data-bind=\"value: $data." + this.getProperty("data") + ", valueUpdate: 'keyup'\""
            + (!!this.getProperty("readonly") ? " disabled" : "")
            + (!!this.getProperty("hint") ? (" title=\"" + this.getProperty("hint") + "\"") : "")
            + (!!this.getProperty("pattern") ? (" pattern=\"" + this.getProperty("pattern") + "\"") : "")
            + (this.getProperty("isnullable") === false ? " required" : "")
            + ">");
    }
}

import { Component, OnInit } from '@angular/core';
import {MenuService} from '../../providers/menu.service';
import {ModalController} from '@ionic/angular';
import {MealmodalComponent} from '../../shared/mealmodal/mealmodal.component';

@Component({
  selector: 'meal',
  templateUrl: './meal.component.html',
  styleUrls: ['./meal.component.scss'],
})
export class MealComponent implements OnInit {

  meals = [{
    mealId:0,
    name:"loading...",
    description: "loading...",
    price:0.00,
  }];


  constructor(public ms:MenuService, public modal: ModalController) { }

  async addMeal(){
      const modal = await this.modal.create({
        component: MealmodalComponent,
      });
      await modal.present();
      await this.refreshMeals();
  }

  async deleteMeal(mealId){
    await this.ms.deleteMeal(mealId);
    this.refreshMeals();
  }

  async editMeal(meal){
    const modal = await this.modal.create({
        component: MealmodalComponent,
        componentProps: {
          'mealJSON': JSON.stringify(meal)
        }
      });
    await modal.present();
    await this.refreshMeals();
  }

  async refreshMeals(){
    let meals = await this.ms.getMeals();
    this.meals = meals;

  }

  async ngOnInit() {
    await this.refreshMeals();
  }

}

import { strictEqual } from "assert";
import { GeneratorOptions, IGenerator, IGeneratorSettings } from "@manuth/extended-yo-generator";
import { TestContext, TestGenerator } from "@manuth/extended-yo-generator-test";
import { TypeScriptCreatorMapping } from "@manuth/generator-ts-project";
import { TempFile } from "@manuth/temp-files";
import { SourceFile } from "ts-morph";
import { TypeScriptFileMappingTester } from "../TypeScriptFileMappingTester";

/**
 * Registers tests for the {@link TypeScriptFileMappingTester `TypeScriptFileMappingTester<TGenerator, TSettings, TOptions, TFileMapping>`} class for testing.
 */
export function TypeScriptFileMappingTesterTests(): void
{
    suite(
        nameof(TypeScriptFileMappingTester),
        () =>
        {
            let context = TestContext.Default;
            let generator: TestGenerator;
            let testValue: string;
            let outputFile: TempFile;
            let fileMapping: TestTypeScriptCreatorMapping;
            let tester: TestTypeScriptFileMappingTester;

            /**
             * Provides an implementation of the {@link TypeScriptCreatorMapping `TypeScriptCreatorMapping<TSettings, TOptions>`} class for testing.
             */
            class TestTypeScriptCreatorMapping extends TypeScriptCreatorMapping<IGeneratorSettings, GeneratorOptions>
            {
                /**
                 * @inheritdoc
                 */
                public get Destination(): string
                {
                    return outputFile.FullName;
                }

                /**
                 * @inheritdoc
                 *
                 * @param sourceFile
                 * The source-file to process.
                 *
                 * @returns
                 * The processed data.
                 */
                protected override async Transform(sourceFile: SourceFile): Promise<SourceFile>
                {
                    sourceFile = await super.Transform(sourceFile);

                    sourceFile.addExportAssignment(
                        {
                            expression: JSON.stringify(testValue)
                        });

                    return sourceFile;
                }
            }

            /**
             * Provides an implementation of the {@link TypeScriptFileMappingTester `TypeScriptFileMappingTester<TGenerator, TSettings, TOptions, TFileMapping>`} class for testing.
             */
            class TestTypeScriptFileMappingTester extends TypeScriptFileMappingTester<IGenerator<IGeneratorSettings, GeneratorOptions>, IGeneratorSettings, GeneratorOptions, TestTypeScriptCreatorMapping>
            { }

            suiteSetup(
                async function()
                {
                    this.timeout(30 * 1000);
                    generator = await context.Generator;
                });

            setup(
                async () =>
                {
                    testValue = context.RandomString;

                    outputFile = new TempFile(
                        {
                            Suffix: ".ts"
                        });

                    fileMapping = new TestTypeScriptCreatorMapping(generator);
                    tester = new TestTypeScriptFileMappingTester(generator, fileMapping);
                    await tester.Run();
                });

            teardown(
                () =>
                {
                    outputFile.Dispose();
                });

            suite(
                nameof<TestTypeScriptFileMappingTester>((tester) => tester.Require),
                () =>
                {
                    test(
                        "Checking whether typescript-files can be required…",
                        async function()
                        {
                            this.timeout(30 * 1000);
                            this.slow(15 * 1000);
                            strictEqual(await tester.Require(), testValue);
                        });
                });
        });
}

'use strict';

import { Uri } from 'vscode';

export function fromCcUri(uri: Uri): { path: string; version: string } {
	return JSON.parse(uri.query);
}

export function toCcUri(uri: Uri, ver: string): Uri {
	return uri.with({
		scheme: 'cc-orig',
		path: uri.path,
		query: JSON.stringify({
            path: uri.fsPath,
            version: ver
		})
	});
}

