import { Component, OnInit } from '@angular/core';

// Application specific imports.
import { FeedbackService } from '../../../../services/feedback.service';
import { ConfigService } from 'src/app/components/management/config/services/config.service';

// CodeMirror options.
import json from '../../../codemirror/options/json.json'
import { AuthService } from '../../auth/services/auth.service';

/**
 * Component that allows user to edit his configuration file as raw JSON.
 */
@Component({
  selector: 'app-config-editor',
  templateUrl: './config-editor.component.html'
})
export class ConfigEditorComponent implements OnInit {

  /**
   * CodeMirror options object, taken from common settings.
   */
  public cmOptions = {
    json: json,
  };

  /**
   * Raw configuration settings as returned from backend.
   */
  public config: string = null;

  /**
   * Creates an instance of your component.
   * 
   * @param feedbackService Needed to display feedback to user
   * @param configService Needed to load and save configuration file
   * @param authService Needed to verify user has access to components
   */
  constructor(
    private feedbackService: FeedbackService,
    private configService: ConfigService,
    public authService: AuthService) {
  }

  /**
   * OnInit implementation.
   */
  public ngOnInit() {

    // Fetching config from backend.
    this.loadConfig();

    // Associating ALT+M with fullscreen toggling of the editor instance.
    this.cmOptions.json.extraKeys['Alt-M'] = (cm: any) => {
      cm.setOption('fullScreen', !cm.getOption('fullScreen'));

      // to hide/show sidenav
      let sidenav = document.querySelector('.mat-sidenav');
      sidenav.classList.contains('d-none') ? sidenav.classList.remove('d-none') :
      sidenav.classList.add('d-none');
    };
  }

  /**
   * Loads configuration from backend.
   */
  public loadConfig() {

    // Fetching raw config from backend.
    this.configService.loadConfig().subscribe((res: any) => {

      // Creating a JSON object out of result, that will be displayed in CodeMirror instance.
      this.config = JSON.stringify(res, null, 2);

    }, (error: any) => this.feedbackService.showError(error));
  }

  /**
   * Saves your configuration.
   */
  public save() {

    // In case conversion to JSON fails.
    try {

      // Converting configuration to JSON.
      const config = JSON.parse(this.config);

      // Saving config by invoking backend.
      this.configService.saveConfig(config).subscribe(() => {

        // Giving user feedback about operation.
        this.feedbackService.showInfo('Configuration was successfully saved');

    }, (error: any) => this.feedbackService.showError(error));
    }
    catch (error) {
      this.feedbackService.showError(error);
    }
  }
}

import { DefaultOptions } from "../src/default-options";
import { writeFileSync } from "fs";
import { join as joinPath } from "path";
import { FaUserAgentIcon } from "../src";

function code(txt: string) {
  return `\`${txt}\``;
}

function jsonCode(value: any) {
 return code(JSON.stringify(value));
}

function row(...cells: string[]) {
  return cells.join(" | ");
}

function codeRow(name: string, value: string) {
  return `${row(code(name), code(value))} |`;
}

function iconRow(name: string, icon: FaUserAgentIcon) {
  const iconHtml = `![${icon.name}](icons/${icon.name}.svg)`;
  return row(code(name), jsonCode(icon), iconHtml);
}

function css(url: string) {
  return `<link rel="stylesheet" type="text/css" media="all" href=${url} />`;
}

const md = `# Default Options

${css("https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.9.0/css/all.min.css")}

Name | Value | Icon
--- | --- | ---
${codeRow("prefix", DefaultOptions.prefix)}
${Object.keys(DefaultOptions.icons)
  .map(category => {
    const cIcons = DefaultOptions.icons[category];
    return Object.keys(cIcons).map(key =>
      iconRow(`icons.${category}.${key}`, cIcons[key])
    );
  })
  .reduce((acc, arr) => [...acc, ...arr], [])
  .join("\n")}
${Object.keys(DefaultOptions.default)
  .map(category =>
    iconRow(`default.${category}`, DefaultOptions.default[category])
  )
  .join("\n")}
`;

const file = joinPath(__dirname, "..", "doc", "default-options.md");

writeFileSync(file, md);

import chalk = require('chalk');
import { memoryFile } from '../../help';
import { watchPath, watchStyleSheet, hmrStyleSheetPath } from '../utils/constant';

let timed: any = null;

export default (state: any) => {
  const reference = state?.file?.opts.filename;
  if (!global.storeStyleSheet) {
    global.storeStyleSheet = {};
  }
  global.storeStyleSheet[reference] = state.css;

  if (global.style_change_hmr && global.style_hmr) {
    if (global.style_hmr_tip) {
      global.style_hmr_tip = false;
      console.info(chalk.yellow('[award-style:hmr]\n'));
    }
    let content = state.css;
    if (memoryFile.existsSync(hmrStyleSheetPath)) {
      content += memoryFile.readFileSync(hmrStyleSheetPath, 'utf-8');
    }
    memoryFile.writeFileSync(hmrStyleSheetPath, content);
  }

  // 通过防抖策略，处理样式
  if (timed) {
    clearTimeout();
  }
  timed = setTimeout(() => {
    // 写main.css
    let content = '';
    for (const key in global.storeStyleSheet) {
      if (Object.prototype.hasOwnProperty.call(global.storeStyleSheet, key)) {
        content = content + global.storeStyleSheet[key];
      }
    }
    memoryFile.writeFileSync(watchStyleSheet, content);
  }, 0);

  // 写css文件资源映射信息到内存文件中
  let map = state.styleSourceMap;
  if (memoryFile.existsSync(watchPath)) {
    map = JSON.parse(memoryFile.readFileSync(watchPath, 'utf-8'));
    for (const stylePath in state.styleSourceMap) {
      if (Object.prototype.hasOwnProperty.call(state.styleSourceMap, stylePath)) {
        const references = state.styleSourceMap[stylePath];
        // map中存在已经该样式的path
        if (map[stylePath]) {
          references.forEach((reference: string) => {
            if (map[stylePath].indexOf(reference) === -1) {
              // push当前样式对应的js引用不存在的文件
              map[stylePath].push(reference);
            }
          });
        } else {
          map[stylePath] = references;
        }
      }
    }
  }
  memoryFile.writeFileSync(watchPath, JSON.stringify(map));
};

