import { stringify } from 'querystring';
import { ProxyResponse, filterHeaders } from './proxy';
import { Config } from './config';

export interface Headers {
  [header: string]: string;
}

export interface IncomingRequest {
  requestId: string;
  requestMethod: string;
  requestPath: string;
  requestHeaders: Headers;
  requestBody: object | string;
}

// @see https://docs.aws.amazon.com/apigateway/latest/developerguide/set-up-lambda-proxy-integrations.html#api-gateway-simple-proxy-for-lambda-output-format
export interface LambdaResponse {
  statusCode: number;
  body?: string;
  isBase64Encoded?: boolean;
  headers?: Headers;
}

export interface LambdaHandlers {
  handler: (
    event: any,
    context: any,
    callback: (error: Error | null, response: LambdaResponse) => void,
  ) => void;
}

// Note: This assumes a request pipeline of CloudFront -> API Gateway -> Lambda
export function normalizeIncomingRequest(event: any): IncomingRequest {
  const query = stringify(event.queryStringParameters);
  return {
    requestId: event.requestContext.requestId,
    requestMethod: event.httpMethod,
    requestPath: event.path + (query ? `?${query}` : ''),
    requestHeaders: event.headers || {},
    requestBody: event.body,
  };
}

export function responseToLambda(
  primary: ProxyResponse,
  config: Config,
): LambdaResponse {
  return {
    statusCode: primary.status,
    body:
      typeof primary.data === 'string'
        ? primary.data
        : JSON.stringify(primary.data),
    isBase64Encoded: false,
    headers: {
      ...filterHeaders(primary.headers, config.proxiedOutgoingHeaders),
      ...config.additionalOutgoingHeaders,
    },
  };
}

import {Client} from 'discord.js';
import {Injectable, Logger, OnApplicationBootstrap, OnApplicationShutdown} from '@nestjs/common';
import {DiscordModuleOptions} from './interfaces/discordmodule.options';

@Injectable()
export class DiscordClient extends Client implements OnApplicationBootstrap, OnApplicationShutdown {
    private static readonly logger = new Logger('DiscordClient');

    constructor(options: DiscordModuleOptions) {
        super(options);

        this.token = options.token;

        this.prepareListeners();
    }

    async onApplicationBootstrap(): Promise<void> {
        DiscordClient.logger.log('Connecting client');

        await this.login();
    }

    onApplicationShutdown(): void {
        this.destroy();

        DiscordClient.logger.log('Client destroyed');
    }

    private prepareListeners(): void {
        this.on('error', (error) => {
            DiscordClient.logger.error(error.message, error.stack);

            process.exit(1);
        });

        this.on('shardError', (error, shard) => DiscordClient.logger.error(error.message, error.stack, `DiscordShard${shard}`));


        this.on('debug', (info) => DiscordClient.logger.verbose(info));
        this.on('guildUnavailable', ({
                                         name,
                                         id,
                                     }) => DiscordClient.logger.log(`Guild became unavailable: ${name}(${id})`));
        this.on('rateLimit', (info) => DiscordClient.logger.debug(`Rate limited: ${JSON.stringify(info)}`));
        this.on('ready', () => DiscordClient.logger.log('Client ready'));
        this.on('warn', (warning) => DiscordClient.logger.warn(warning));
        this.on('shardDisconnect', ({
                                        reason = 'No reason given',
                                        code = NaN,
                                    }, shard) => DiscordClient.logger.verbose(`Shard disconnected: ${reason}(${code})`, `DiscordShard${shard}`));
        this.on('shardReady', (shard) => DiscordClient.logger.verbose('Shard ready', `DiscordShard${shard}`));
        this.on('shardReconnecting', (shard) => DiscordClient.logger.verbose('Shard reconnecting', `DiscordShard${shard}`));
        this.on('shardResume', (replayed, shard) => DiscordClient.logger.verbose(`Shard resumed: ${replayed}`, `DiscordShard${shard}`));
    }
}

import { ISSearchParams } from './types'
import { isString } from './utils'

function replaceHighlightTags(
  value: string,
  highlightPreTag?: string,
  highlightPostTag?: string
): string {
  // Value has to be a string to have highlight.
  // Highlight is applied by MeiliSearch (<em> tags)
  // We replace the <em> by the expected tag for InstantSearch
  highlightPreTag = highlightPreTag || '__ais-highlight__'
  highlightPostTag = highlightPostTag || '__/ais-highlight__'
  if (isString(value)) {
    return value
      .replace(/<em>/g, highlightPreTag)
      .replace(/<\/em>/g, highlightPostTag)
  }
  // We JSON stringify to avoid loss of nested information
  return JSON.stringify(value)
}

function createHighlighResult<T extends Record<string, any>>({
  formattedHit,
  highlightPreTag,
  highlightPostTag,
}: { formattedHit: T } & ISSearchParams) {
  // formattedHit is the `_formatted` object returned by MeiliSearch.
  // It contains all the highlighted and croped attributes
  return Object.keys(formattedHit).reduce((result, key) => {
    ;(result[key] as any) = {
      value: replaceHighlightTags(
        formattedHit[key],
        highlightPreTag,
        highlightPostTag
      ),
    }
    return result
  }, {} as T)
}

function snippetFinalValue(
  value: string,
  snippetEllipsisText?: string,
  highlightPreTag?: string,
  highlightPostTag?: string
) {
  let newValue = value
  // manage a kind of `...` for the crop until this issue is solved: https://github.com/meilisearch/MeiliSearch/issues/923
  // `...` is put if we are at the middle of a sentence (instead at the middle of the document field)
  if (snippetEllipsisText !== undefined && isString(newValue)) {
    if (
      newValue[0] === newValue[0].toLowerCase() && // beginning of a sentence
      newValue.startsWith('<em>') === false // beginning of the document field, otherwise MeiliSearch would crop around the highligh
    ) {
      newValue = `${snippetEllipsisText}${newValue}`
    }
    if (!!newValue.match(/[.!?]$/) === false) {
      // end of the sentence
      newValue = `${newValue}${snippetEllipsisText}`
    }
  }
  return replaceHighlightTags(newValue, highlightPreTag, highlightPostTag)
}

function createSnippetResult<
  T extends Record<string, any>,
  K extends keyof T & string
>({
  formattedHit,
  attributesToSnippet,
  snippetEllipsisText,
  highlightPreTag,
  highlightPostTag,
}: { formattedHit: T } & ISSearchParams) {
  if (attributesToSnippet === undefined) {
    return null
  }
  attributesToSnippet = attributesToSnippet.map(
    (attribute) => attribute.split(':')[0]
  ) as K[]
  // formattedHit is the `_formatted` object returned by MeiliSearch.
  // It contains all the highlighted and croped attributes
  return (Object.keys(formattedHit) as K[]).reduce((result, key) => {
    if (attributesToSnippet!.includes(key)) {
      ;(result[key] as any) = {
        value: snippetFinalValue(
          formattedHit[key],
          snippetEllipsisText,
          highlightPreTag,
          highlightPostTag
        ),
      }
    }
    return result
  }, {} as T)
}

export { createHighlighResult, createSnippetResult }

