import { RestManager } from "../bot.ts";

/** Processes the queue by looping over each path separately until the queues are empty. */
export function processQueue(rest: RestManager, id: string) {
  const queue = rest.pathQueues.get(id);
  if (!queue) return;

  while (queue.requests.length) {
    rest.debug(`[REST - processQueue] Running while loop.`);
    // SELECT THE FIRST ITEM FROM THIS QUEUE
    const queuedRequest = queue.requests[0];
    // IF THIS DOESN'T HAVE ANY ITEMS JUST CANCEL, THE CLEANER WILL REMOVE IT.
    if (!queuedRequest) break;

    const basicURL = rest.simplifyUrl(queuedRequest.request.url, queuedRequest.request.method.toUpperCase());

    // IF THIS URL IS STILL RATE LIMITED, TRY AGAIN
    const urlResetIn = rest.checkRateLimits(rest, basicURL);
    if (urlResetIn) {
      // ONLY ADD TIMEOUT IF ANOTHER QUEUE IS NOT PENDING
      if (!queue.isWaiting) {
        queue.isWaiting = true;

        setTimeout(() => {
          queue.isWaiting = false;

          rest.debug(`[REST - processQueue] rate limited, running setTimeout.`);
          rest.processQueue(rest, id);
        }, urlResetIn);
      }

      // BREAK WHILE LOOP
      break;
    }

    // IF A BUCKET EXISTS, CHECK THE BUCKET'S RATE LIMITS
    const bucketResetIn = queuedRequest.payload.bucketId
      ? rest.checkRateLimits(rest, queuedRequest.payload.bucketId)
      : false;
    // THIS BUCKET IS STILL RATE LIMITED, RE-ADD TO QUEUE
    if (bucketResetIn) continue;
    // EXECUTE THE REQUEST

    // CUSTOM HANDLER FOR USER TO LOG OR WHATEVER WHENEVER A FETCH IS MADE
    rest.debug(`[REST - Add To Global Queue] ${JSON.stringify(queuedRequest.payload)}`);
    rest.globalQueue.push({
      ...queuedRequest,
      urlToUse: queuedRequest.request.url,
      basicURL,
    });
    rest.processGlobalQueue(rest);
    queue.requests.shift();
  }

  // ONCE QUEUE IS DONE, WE CAN TRY CLEANING UP
  rest.cleanupQueues(rest);
}

import * as runtypes from 'runtypes';
import { AES, enc } from "crypto-js";

const StreamDataRuntime = runtypes.Record({
    id:      runtypes.String,
    enabled: runtypes.Boolean,
}).Or(runtypes.Undefined)

const StreamMap = runtypes.Dictionary(StreamDataRuntime)

const ConnectionICERuntime = runtypes.Record({ 
    user_guid: runtypes.String,
    candidate: runtypes.String,
    conn_guid: runtypes.String,
});

type ConnectionICE = runtypes.Static<typeof ConnectionICERuntime>;

const ConnectionOfferRuntime = runtypes.Record({ 
    user_guid:   runtypes.String,
    description: runtypes.String,
    conn_guid:   runtypes.String,
    stream_map:  StreamMap,
});

type ConnectionOffer = runtypes.Static<typeof ConnectionOfferRuntime>;

const MessagesRuntype = {
    "p2p-on-ice":                    ConnectionICERuntime,
    "p2p-offer":                     ConnectionOfferRuntime,
}

export type EncryptedMessages = {
    "p2p-on-ice":                    ConnectionICE
    "p2p-offer":                     ConnectionOffer
}

export type EncryptedMessage = {
    message:        string
}

export const Encrypt = <K extends keyof EncryptedMessages>(encryption_key: string, marker: K, message: EncryptedMessages[K]):string => {
    return AES.encrypt(JSON.stringify({ marker, message }), encryption_key).toString();
}

export const Decrypt = <K extends keyof EncryptedMessages>(encryption_key: string, marker: K, message: string):[EncryptedMessages[K], null] |  [null, string] => {
    const bytes = AES.decrypt(message, encryption_key);
    const res = JSON.parse(bytes.toString(enc.Utf8));

    if (res && res.marker === marker && res.message) {
        if (res.message !== null) {
            const status = MessagesRuntype[marker].validate(res.message);
            if (!status.success) {
                return [ null, "runtime validation error" ];
            } else {
                return [ res.message, null ]
            }
        }
    }

    return [ null, "Bad data" ];
}

