            className={`px-1 xs:px-4 cursor-pointer grid place-items-center transition-colors duration-300 ${
              variant === state.variant ? 'bg-primary text-white' : 'bg-card'
            }`}
            key={variant}
          >
            {variant}
          </span>
        ))}
      </div>
    </>
  )
}
const DropDownList = ({ state, dispatch }: ListProps) => {
