import { Injectable } from '@angular/core'
import { TenantService } from './tenant.service'
import * as Raven from 'raven-js'
import { environment } from '../../../environments/environment'
import { Observable } from 'rxjs/Observable'

interface ErrorInfo {
    module: string
    method: string
    description: string
}

interface HttpErrorInfo {
    module: string
    method: string
    error: any
}

/*
  Generated class for the LoggerProvider provider.

  See https://angular.io/docs/ts/latest/guide/dependency-injection.html
  for more info on providers and Angular 2 DI.
*/
@Injectable()
export class ErrorLoggerService {
    constructor(private tenantService: TenantService) { }

    /**
     * info 级别日志记录
     *
     * @param {ErrorInfo} error
     * @returns {(Promise<any> | void)}
     * @memberof ErrorLoggerService
     */
    info(error: ErrorInfo): Promise<any> | void {
        if (environment.production) {
            return this.postErrorMessage(
                error.module,
                'INFO',
                error.method,
                error.description
            )
        } else {
            console.info(
                `Module: ${error.module}; Method: ${
                error.method
                }; description: ${error.description};`
            )
        }
    }

    /**
     * error 级别日志记录
     *
     * @param {ErrorInfo} error
     * @returns {(Promise<any> | void)}
     * @memberof ErrorLoggerService
     */
    error(error: ErrorInfo): Promise<any> | void {
        if (environment.production) {
            return this.postErrorMessage(
                error.module,
                'ERROR',
                error.method,
                error.description
            )
        } else {
            console.error(
                `Module: ${error.module}; Method: ${
                error.method
                }; description: ${error.description};`
            )
        }
    }
    /**
     * 记录 Http error
     *
     * @param {HttpErrorInfo} info
     * @returns {Observable<any>}
     * @memberof ErrorLoggerService
     */
    httpError(info: HttpErrorInfo): Observable<any> {
        const errMsg = info.error.message
            ? info.error.message
            : info.error.status
                ? `${info.error.status} - ${info.error.statusText}`
                : 'Server error'

        this.error({
            module: info.module,
            method: info.method,
            description: errMsg
        })

        return Observable.throw(new Error(errMsg))
    }

    /**
     * 调用 Sentry.io 实现
     * https://docs.sentry.io/clients/javascript/integrations/angular/
     *
     * @private
     * @param {string} module
     * @param {string} level
     * @param {string} method
     * @param {string} description
     * @returns {Promise<any>}
     * @memberof ErrorLoggerService
     */
    private postErrorMessage(
        module: string,
        level: string,
        method: string,
        description: string
    ): Promise<any> {
        const tenantId = this.tenantService.getTenantID()
        const userId = this.tenantService.getUserID()
        return Promise.resolve().then(() => {
            const msg = `Module: ${module}, Method: ${method}, TenantId: ${tenantId}, UserId: ${userId}, description: ${description}`

            Raven.captureMessage(
                msg,
                level === 'INFO' ? { level: 'info' } : undefined
            )
        })
    }
}

